// The door reads `$1FBC` through the data bank, which is the handler's own.
static bool accepts_exit_door(const Wram* w, const CosimRegs* in) {
  (void)w;
  return in->db < 0x40 || (in->db >= 0x80 && in->db < 0xc0);
}

