static const CosimRun MARTIAN_RUN_SHOW_CAP = {18, 3, 0};      // $9CA8 LDA #$0008
static const CosimRun MARTIAN_RUN_SHOW_SET = {40, 3, 0};      // $9CAB JSR $9C8F
static const CosimRun MARTIAN_RUN_SHOW_FLAGS = {126, 12, 2};  // $9CAE-$9CB9
