static const CosimRun MARTIAN_RUN_CYCLE_NEXT = {232, 23, 3};  // $9E91-$9EA5
// Arriving.
static const CosimRun MARTIAN_RUN_ARRIVE_HEAD = {152, 14, 2};    // $9DBB-$9DC8
static const CosimRun MARTIAN_RUN_ARRIVE_ABOVE = {52, 5, 0};     // $9DCB JSR : BCS
static const CosimRun MARTIAN_RUN_ABOVE_PLAYER = {46, 5, 0};     // LDY $00D2 : BEQ
static const CosimRun MARTIAN_RUN_ABOVE_COMPARE = {80, 7, 1};    // LDA CMP BCC
static const CosimRun MARTIAN_RUN_ABOVE_ANSWER = {52, 2, 0};     // CLC : RTS
static const CosimRun MARTIAN_RUN_ARRIVE_DESCEND = {74, 7, 2};   // $9E49-$9E4F
static const CosimRun MARTIAN_RUN_BECOME_WALKER = {86, 6, 1};    // $9D2A-$9D2F
static const CosimRun MARTIAN_RUN_ARRIVE_ALIGN = {134, 11, 2};   // $9DD0-$9DDA
static const CosimRun MARTIAN_RUN_ARRIVE_SHOOT = {52, 5, 0};     // $9DDB JSR : BRA
static const CosimRun MARTIAN_RUN_ARRIVE_DRAW = {84, 9, 0};      // $9DE0-$9DE8
static const CosimRun MARTIAN_RUN_ARRIVE_FIRE = {58, 6, 0};      // $9DE9 LDA : JSR
static const CosimRun MARTIAN_RUN_ARRIVE_TIMER = {62, 4, 1};     // $9DEF DEC $34 : BPL
static const CosimRun MARTIAN_RUN_ARRIVE_LOOK = {270, 24, 6};    // $9DF3-$9E0A
static const CosimRun MARTIAN_RUN_ARRIVE_FAR = {164, 12, 2};     // $9E0B-$9E16
static const CosimRun MARTIAN_RUN_ARRIVE_CLOSE = {242, 23, 2};   // $9E50-$9E64
static const CosimRun MARTIAN_RUN_ARRIVE_SIDE = {48, 8, 0};      // $9E17-$9E1E
static const CosimRun MARTIAN_RUN_ARRIVE_SIDE_LEFT = {18, 3, 0}; // LDY #
static const CosimRun MARTIAN_RUN_ARRIVE_SIDE_SET = {28, 2, 1};  // $9E22 STY $36
static const CosimRun MARTIAN_RUN_ARRIVE_HEIGHT = {176, 14, 4};  // $9E24-$9E31
static const CosimRun MARTIAN_RUN_ARRIVE_SLANT = {76, 10, 1};    // $9E65-$9E6E
static const CosimRun MARTIAN_RUN_ARRIVE_TWICE = {80, 7, 1};     // $9E72-$9E78

// The ROM's own instructions in `own`, and what its calls cost in `calls`.
typedef struct {
  CosimRun own;
  int calls;
  const MartianLog* log;
  const CosimRegs* in;
} MartianBill;

static void martian_add(MartianBill* b, const CosimRun* r) {
  run_add(&b->own, r, 1);
}

static void martian_taken(MartianBill* b) {
  martian_add(b, &MARTIAN_RUN_TAKEN);
}

// A shot that only counted one off. `through_pointer` is by `$81:9D1F`,
// which calls whatever `$22` names and has an `RTS` of its own.
static void martian_shoot_bill(MartianBill* b, bool through_pointer) {
  if (through_pointer) martian_add(b, &MARTIAN_RUN_SHOOT_VIA);
  martian_add(b, &MARTIAN_RUN_SHOOT_HEAD);
  martian_taken(b);
  martian_add(b, &MARTIAN_RUN_SHOOT_WAIT);
  if (through_pointer) martian_add(b, &MARTIAN_RUN_RTS);
}

static void martian_bearing_bill(MartianBill* b) {
  b->calls += actor_snap_cycles(&b->log->snap, b->in->fastrom) +
              actor_bearing_cycles(&b->log->bearing, b->in->fastrom);
}

// One axis of a step: each test that let it by is followed by the next.
static void martian_axis_bill(MartianBill* b, const MartianProbe* p) {
  martian_add(b, &MARTIAN_RUN_STEP_GROUND);
  b->calls += terrain_enemy_cycles(&p->ground, b->in->fastrom);
  if (p->ground.blocked) {
    martian_taken(b);
    return;
  }
  martian_add(b, &MARTIAN_RUN_STEP_EDGE);
  b->calls += bounds_cycles(p->edge, b->in->fastrom);
  if (p->outside) {
    martian_taken(b);
    return;
  }
  martian_add(b, &MARTIAN_RUN_STEP_ACTOR);
  if (p->someone)
    martian_taken(b);
  else
    martian_add(b, &MARTIAN_RUN_STEP_TAKE);
}

static void martian_step_bill(MartianBill* b, const MartianStep* s) {
  martian_add(b, &MARTIAN_RUN_STEP_HEAD);
  if (s->rested) {
    martian_taken(b);
    martian_add(b, &MARTIAN_RUN_RTS);
    return;
  }
  martian_add(b, &MARTIAN_RUN_STEP_TRY);
  martian_axis_bill(b, &s->axis[0]);
  martian_axis_bill(b, &s->axis[1]);
  martian_add(b, &MARTIAN_RUN_STEP_PUBLISH);
}

static void martian_line_up_bill(MartianBill* b) {
  const MartianLog* log = b->log;
  martian_add(b, &MARTIAN_RUN_LINE_X);
  martian_add(b, log->gap_x_negative ? &MARTIAN_RUN_NEGATE : &MARTIAN_RUN_TAKEN);
  martian_add(b, &MARTIAN_RUN_LINE_Y);
  martian_add(b, log->gap_y_negative ? &MARTIAN_RUN_NEGATE : &MARTIAN_RUN_TAKEN);
  martian_add(b, &MARTIAN_RUN_LINE_CMP);
  if (log->along_y) martian_taken(b);
  martian_add(b, &MARTIAN_RUN_LINE_PICK);
  if (log->lesser_sign == 0) {
    martian_taken(b);
    martian_add(b, &MARTIAN_RUN_RTS);
    return;
  }
  martian_add(b, &MARTIAN_RUN_LINE_SIGN);
  if (log->lesser_sign > 0) martian_taken(b);
  martian_add(b, &MARTIAN_RUN_LINE_ANSWER);
}

static void martian_show_bill(MartianBill* b) {
  const MartianLog* log = b->log;
  martian_add(b, &MARTIAN_RUN_SHOW_PICK);
  martian_add(b, log->capped ? &MARTIAN_RUN_SHOW_CAP : &MARTIAN_RUN_TAKEN);
  martian_add(b, &MARTIAN_RUN_SHOW_SET);
  martian_add(b, &MARTIAN_RUN_PICTURE);
  martian_add(b, &MARTIAN_RUN_SHOW_FLAGS);
  martian_add(b, log->mirrored ? &MARTIAN_RUN_SHOW_MIRROR
                               : &MARTIAN_RUN_SHOW_PLAIN);
  martian_taken(b);  // the `BCS` to the mirror, or the `BRA` round it
  martian_add(b, &MARTIAN_RUN_SHOW_STORE);
  martian_add(b, log->new_picture ? &MARTIAN_RUN_SHOW_NEXT : &MARTIAN_RUN_TAKEN);
  martian_add(b, &MARTIAN_RUN_RTS);
}

// From `$81:9D3E`: the look and the step.
static void martian_walk_on_bill(MartianBill* b);

// A walker's pass that fires stops at the `JSL` that asks for the shot's
// thread.
static void martian_walk_bill(MartianBill* b) {
  const MartianLog* log = b->log;
  const bool fast = b->in->fastrom;
  martian_add(b, &MARTIAN_RUN_WALK_ALIGN);
  b->calls += aligned_cycles(&log->aligned, fast);
  if (log->fired) {
    martian_add(b, &MARTIAN_RUN_SHOOT_JSR);
    martian_add(b, &MARTIAN_RUN_SHOOT_VIA);
    martian_add(b, &MARTIAN_RUN_SHOOT_HEAD);
    martian_add(b, &MARTIAN_RUN_FIRE_SET);
    martian_add(b, &MARTIAN_RUN_PICTURE);
    martian_add(b, &MARTIAN_RUN_FIRE_FLAGS);
    martian_add(b, log->shot_mirrored ? &MARTIAN_RUN_SHOW_MIRROR
                                      : &MARTIAN_RUN_SHOW_PLAIN);
    martian_taken(b);
    martian_add(b, &MARTIAN_RUN_FIRE_STORE);
    return;
  }
  if (log->held_fire) {
    martian_add(b, &MARTIAN_RUN_SHOOT_JSR);
    martian_shoot_bill(b, true);
  } else {
    martian_taken(b);
  }
  martian_walk_on_bill(b);
}

static void martian_walk_on_bill(MartianBill* b) {
  const MartianLog* log = b->log;
  const bool fast = b->in->fastrom;
  martian_add(b, &MARTIAN_RUN_WALK_TIMER);
  if (log->look == MARTIAN_LOOK_NONE) {
    martian_taken(b);
  } else {
    martian_add(b, &MARTIAN_RUN_WALK_LOOK);
    b->calls += nearest_cycles(&log->nearest, fast);
    switch (log->look) {
      case MARTIAN_LOOK_BACK_OFF:
        martian_taken(b);
        martian_add(b, &MARTIAN_RUN_WALK_CLOSE);
        martian_taken(b);
        martian_bearing_bill(b);
        break;
      case MARTIAN_LOOK_LINE_UP:
        martian_add(b, &MARTIAN_RUN_BAND);
        martian_taken(b);
        martian_add(b, &MARTIAN_RUN_WALK_MID);
        martian_line_up_bill(b);
        break;
      case MARTIAN_LOOK_APPROACH:
        martian_add(b, &MARTIAN_RUN_BAND);
        martian_add(b, &MARTIAN_RUN_BAND);
        martian_taken(b);
        martian_add(b, &MARTIAN_RUN_WALK_FAR);
        martian_taken(b);
        martian_bearing_bill(b);
        break;
      default:
        martian_add(b, &MARTIAN_RUN_BAND);
        martian_add(b, &MARTIAN_RUN_BAND);
        martian_add(b, &MARTIAN_RUN_WALK_GONE);
        b->calls += player_bearing_cycles(&log->players, fast);
        martian_add(b, log->look == MARTIAN_LOOK_LEAVE ? &MARTIAN_RUN_LEAVE
                                                       : &MARTIAN_RUN_TAKEN);
        martian_add(b, &MARTIAN_RUN_RTS);
        return;
    }
    martian_add(b, &MARTIAN_RUN_WALK_FACE);
  }

  martian_add(b, &MARTIAN_RUN_MOVE);
  martian_step_bill(b, &log->step[0]);
  martian_show_bill(b);
}

// `$81:9EAF`: each player there is, compared, until one is above.
static void martian_above_bill(MartianBill* b) {
  const MartianLog* log = b->log;
  for (int i = 0; i < 2; i++) {
    martian_add(b, &MARTIAN_RUN_ABOVE_PLAYER);
    if (!log->player[i]) {
      martian_taken(b);
      continue;
    }
    martian_add(b, &MARTIAN_RUN_ABOVE_COMPARE);
    if (log->player_above[i]) {
      martian_taken(b);
      break;
    }
  }
  martian_add(b, &MARTIAN_RUN_ABOVE_ANSWER);
}

static void martian_arrive_bill(MartianBill* b) {
  const MartianLog* log = b->log;
  const bool fast = b->in->fastrom;
  martian_add(b, &MARTIAN_RUN_ARRIVE_HEAD);
  b->calls += player_bearing_cycles(&log->players, fast);
  martian_add(b, log->nobody ? &MARTIAN_RUN_LEAVE : &MARTIAN_RUN_TAKEN);
  martian_add(b, &MARTIAN_RUN_ARRIVE_ABOVE);
  martian_above_bill(b);
  if (log->came_down) {
    martian_taken(b);
    martian_add(b, &MARTIAN_RUN_ARRIVE_DESCEND);
    martian_add(b, &MARTIAN_RUN_BECOME_WALKER);
    return;
  }

  martian_add(b, &MARTIAN_RUN_ARRIVE_ALIGN);
  b->calls += aligned_cycles(&log->aligned, fast);
  if (log->held_fire) {
    martian_add(b, &MARTIAN_RUN_ARRIVE_SHOOT);
    martian_taken(b);
    martian_shoot_bill(b, true);
  } else {
    martian_taken(b);
    martian_add(b, &MARTIAN_RUN_ARRIVE_DRAW);
    b->calls += rng_cycles(log->drew_overflow, fast);
    if (log->drew_fire) {
      martian_add(b, &MARTIAN_RUN_ARRIVE_FIRE);
      martian_shoot_bill(b, false);
    } else {
      martian_taken(b);
    }
  }

  martian_add(b, &MARTIAN_RUN_ARRIVE_TIMER);
  if (log->picked_side) {
    martian_add(b, &MARTIAN_RUN_ARRIVE_LOOK);
    b->calls += nearest_cycles(&log->nearest, fast);
    if (log->target_close) {
      martian_taken(b);
      martian_add(b, &MARTIAN_RUN_ARRIVE_CLOSE);
      martian_taken(b);
    } else {
      martian_add(b, &MARTIAN_RUN_ARRIVE_FAR);
    }
    martian_bearing_bill(b);
    martian_add(b, &MARTIAN_RUN_ARRIVE_SIDE);
    martian_add(b, log->side_left ? &MARTIAN_RUN_ARRIVE_SIDE_LEFT
                                  : &MARTIAN_RUN_TAKEN);
    martian_add(b, &MARTIAN_RUN_ARRIVE_SIDE_SET);
  } else {
    martian_taken(b);
  }

  martian_add(b, &MARTIAN_RUN_ARRIVE_HEIGHT);
  martian_add(b, log->height_negative ? &MARTIAN_RUN_NEGATE : &MARTIAN_RUN_TAKEN);
  martian_add(b, &MARTIAN_RUN_BAND);
  if (log->height != MARTIAN_HEIGHT_CLIMB) martian_add(b, &MARTIAN_RUN_BAND);
  if (log->height != MARTIAN_HEIGHT_KEEP) {
    martian_taken(b);
    martian_add(b, &MARTIAN_RUN_ARRIVE_SLANT);
    martian_add(b, log->slant_left ? &MARTIAN_RUN_ARRIVE_SIDE_LEFT
                                   : &MARTIAN_RUN_TAKEN);
    martian_add(b, &MARTIAN_RUN_ARRIVE_TWICE);
    martian_taken(b);
  }
  for (int i = 0; i < log->steps; i++) {
    martian_add(b, &MARTIAN_RUN_MOVE);
    martian_step_bill(b, &log->step[i]);
    martian_add(b, &MARTIAN_RUN_CYCLE_TIMER);
    if (log->step[i].new_picture) {
      martian_add(b, &MARTIAN_RUN_CYCLE_NEXT);
      martian_add(b, &MARTIAN_RUN_PICTURE);
    } else {
      martian_taken(b);
    }
    martian_add(b, &MARTIAN_RUN_RTS);
  }
}

// The tests put their scratch on page zero, and the tables and the list of
// pictures are read through the data bank. So are the record and whoever it
// found, which have to be in the WRAM bank `$81` mirrors.
//
// A walker reads its target only on a pass that looks for one, so what it has
// beforehand is no matter.
static bool martian_frame_ok(const Wram* w, const CosimRegs* in) {
  if (!body_ok(in) || in->d < 0x0100 || in->db != MARTIAN_BANK) return false;
  const bool walking =
      wram_r16(w, (uint16_t)(in->d + MARTIAN_DP_STATE)) == MARTIAN_STATE_WALK;
  return wram_r16(w, (uint16_t)(in->d + MARTIAN_DP_RECORD)) < 0x1f00 &&
         (walking ||
          wram_r16(w, (uint16_t)(in->d + MARTIAN_DP_TARGET)) < 0x1f00) &&
         wram_r16(w, (uint16_t)(in->d + MARTIAN_DP_PICTURES)) >= 0x8000 &&
         martian_frame_supported(w, in->d);
}

// Two things only running the pass can find. It fired, which is the ROM's.
// Or it looked, and what `actor_nearest` gave it is no record: with nothing
// to find, that hands back whatever its last search left.
static bool guard_martian_frame(Wram* scratch, const Rom* rom,
                                const CosimRegs* in) {
  MartianLog log = {0};
  martian_frame(scratch, rom, in->d, &log);
  if (log.declined) return false;
  const bool looked = log.look != MARTIAN_LOOK_NONE || log.picked_side;
  return !looked ||
         wram_r16(scratch, (uint16_t)(in->d + MARTIAN_DP_TARGET)) < 0x1f00;
}

// The words a pass has on its stack: the loop's `PEA`, the walk's `JSR` to
// the shot, and the `PEA` the shot is called through. And the two that are
// left behind by the rest of the pass: its `JSR` to the picture, and that
// one's to the setter.
#define MARTIAN_RETURN_WALKER 0x99fdu
#define MARTIAN_RETURN_ARRIVAL 0x9a61u
#define MARTIAN_RETURN_WALK_SHOT 0x9d3du
#define MARTIAN_RETURN_VIA 0x9d28u
#define MARTIAN_RETURN_SHOW 0x9dafu
#define MARTIAN_RETURN_SHOW_SET 0x9cadu

// The end of a pass: the fate's test, and what the calls cost.
static void martian_pass_cost(MartianBill* b, bool stays) {
  martian_add(b, &MARTIAN_RUN_FATE);
  if (stays) {
    martian_taken(b);
    martian_add(b, &MARTIAN_RUN_TICKS);
  }
  b->calls += at_point_cycles(&b->log->at_point, b->in->fastrom);
  cosim_cost(b->calls + cosim_run_cycles_dp(&b->own, fetch_fast(b->in),
                                            (b->in->d & 0x00ffu) != 0));
}

static void martian_pass_leave(const Wram* w, const CosimRegs* in,
                               CosimRegs* out, const MartianLog* log,
                               bool stays, uint32_t yield_pc,
                               uint32_t fate_pc);

// It leaves by the `JSL thread_yield` with the tick count in A, or past the
// test of its fate with that in A. Or, a walker firing, by the `JSL` that
// asks for the shot's thread, with the stack as the ROM has it there.
static void martian_frame_run(Wram* w, const Rom* rom, const CosimRegs* in,
                              CosimRegs* out, uint16_t loop_return,
                              uint32_t yield_pc, uint32_t fate_pc) {
  MartianLog log = {0};
  const bool stays = martian_frame(w, rom, in->d, &log);

  MartianBill b = {{0, 0, 0}, 0, &log, in};
  martian_add(&b, &MARTIAN_RUN_ENTER);
  if (log.state == MARTIAN_STATE_WALK)
    martian_walk_bill(&b);
  else
    martian_arrive_bill(&b);
  if (log.fired) {
    cosim_cost(b.calls + cosim_run_cycles_dp(&b.own, fetch_fast(in),
                                             (in->d & 0x00ffu) != 0));
    out->pc = MARTIAN_SHOOT_SPAWN_PC;
    out->a = MARTIAN_SHOT_THREAD;
    out->x = log.shot_way;
    out->y = MARTIAN_BANK;
    out->regs = COSIM_REG_ALL;
    out->p = (uint8_t)(in->p & ~(PORT_P_N | PORT_P_Z | PORT_P_C | PORT_P_V));
    if (log.shot_mirrored) out->p |= PORT_P_C;
    if (log.v) out->p |= PORT_P_V;
    out->p_keep = (uint8_t)(log.v_set ? 0 : PORT_P_V);
    wram_w16(w, (uint16_t)(in->s - 1), loop_return);
    wram_w16(w, (uint16_t)(in->s - 3), MARTIAN_RETURN_WALK_SHOT);
    wram_w16(w, (uint16_t)(in->s - 5), MARTIAN_RETURN_VIA);
    wram_w16(w, (uint16_t)(in->s - 7), (uint16_t)(MARTIAN_SHOOT - 1));
    out->s = (uint16_t)(in->s - 6);
    return;
  }
  martian_pass_cost(&b, stays);
  martian_pass_leave(w, in, out, &log, stays, yield_pc, fate_pc);
}

static void martian_pass_leave(const Wram* w, const CosimRegs* in,
                               CosimRegs* out, const MartianLog* plog,
                               bool stays, uint32_t yield_pc,
                               uint32_t fate_pc) {
  const MartianLog log = *plog;
  out->pc = stays ? yield_pc : fate_pc;
  out->a = stays ? MARTIAN_YIELD_TICKS
                 : wram_r16(w, (uint16_t)(in->d + MARTIAN_DP_FATE));
  out->regs = COSIM_REG_A;
  out->p = (uint8_t)(in->p & ~(PORT_P_N | PORT_P_Z | PORT_P_C | PORT_P_V));
  if (out->a & 0x8000u) out->p |= PORT_P_N;
  if (log.c) out->p |= PORT_P_C;
  if (log.v) out->p |= PORT_P_V;
  out->p_keep = (uint8_t)((log.c_set ? 0 : PORT_P_C) | (log.v_set ? 0 : PORT_P_V));
}

static void shim_martian_frame(Wram* w, const Rom* rom, const CosimRegs* in,
                               CosimRegs* out) {
  martian_frame_run(w, rom, in, out, MARTIAN_RETURN_WALKER,
                    MARTIAN_WALKER_YIELD_PC, MARTIAN_WALKER_FATE_PC);
}

static void shim_martian_arrival_frame(Wram* w, const Rom* rom,
                                       const CosimRegs* in, CosimRegs* out) {
  martian_frame_run(w, rom, in, out, MARTIAN_RETURN_ARRIVAL,
                    MARTIAN_ARRIVAL_YIELD_PC, MARTIAN_ARRIVAL_FATE_PC);
}

static const uint32_t MARTIAN_FRAME_EXITS[] = {
    MARTIAN_WALKER_YIELD_PC, MARTIAN_WALKER_FATE_PC, MARTIAN_SHOOT_SPAWN_PC};
static const uint32_t MARTIAN_ARRIVAL_FRAME_EXITS[] = {
    MARTIAN_ARRIVAL_YIELD_PC, MARTIAN_ARRIVAL_FATE_PC, MARTIAN_SHOOT_SPAWN_PC};

// `$81:99C9`: the rest of a walking pass that fired. The sleep comes back
// to an `RTS`, and what that goes back through is on the stack: the shot's
// caller, the walk, and whichever loop the pass is of.
static bool accepts_martian_wake(const Wram* w, const CosimRegs* in) {
  if (!martian_frame_ok(w, in) ||
      wram_r16(w, (uint16_t)(in->d + MARTIAN_DP_STATE)) != MARTIAN_STATE_WALK)
    return false;
  const uint16_t loop = wram_r16(w, (uint16_t)(in->s + 5));
  return wram_r16(w, (uint16_t)(in->s + 1)) == MARTIAN_RETURN_VIA &&
         wram_r16(w, (uint16_t)(in->s + 3)) == MARTIAN_RETURN_WALK_SHOT &&
         (loop == MARTIAN_RETURN_WALKER || loop == MARTIAN_RETURN_ARRIVAL);
}

// A look that chose no way returns without the step and the picture, and
// what is left on the stack is then some call's of the look's: the ROM's.
// So is one whose `actor_nearest` gave it no record.
static bool guard_martian_wake(Wram* scratch, const Rom* rom,
                               const CosimRegs* in) {
  MartianLog log = {0};
  martian_wake(scratch, rom, in->d, &log);
  if (log.look == MARTIAN_LOOK_NONE) return true;
  return log.look != MARTIAN_LOOK_STAND && log.look != MARTIAN_LOOK_LEAVE &&
         wram_r16(scratch, (uint16_t)(in->d + MARTIAN_DP_TARGET)) < 0x1f00;
}

static void shim_martian_wake(Wram* w, const Rom* rom, const CosimRegs* in,
                              CosimRegs* out) {
  const bool arrival =
      wram_r16(w, (uint16_t)(in->s + 5)) == MARTIAN_RETURN_ARRIVAL;
  MartianLog log = {0};
  const bool stays = martian_wake(w, rom, in->d, &log);

  MartianBill b = {{0, 0, 0}, 0, &log, in};
  martian_add(&b, &MARTIAN_RUN_RTS);  // the shot's
  martian_add(&b, &MARTIAN_RUN_RTS);  // ...and the one it was called through
  martian_walk_on_bill(&b);
  martian_pass_cost(&b, stays);
  martian_pass_leave(w, in, out, &log, stays,
                     arrival ? MARTIAN_ARRIVAL_YIELD_PC
                             : MARTIAN_WALKER_YIELD_PC,
                     arrival ? MARTIAN_ARRIVAL_FATE_PC
                             : MARTIAN_WALKER_FATE_PC);
  wram_w16(w, (uint16_t)(in->s + 3), MARTIAN_RETURN_SHOW);
  wram_w16(w, (uint16_t)(in->s + 1), MARTIAN_RETURN_SHOW_SET);
  out->s = (uint16_t)(in->s + 6);
}

static const uint32_t MARTIAN_WAKE_EXITS[] = {
    MARTIAN_WALKER_YIELD_PC, MARTIAN_WALKER_FATE_PC, MARTIAN_ARRIVAL_YIELD_PC,
    MARTIAN_ARRIVAL_FATE_PC};

// `$81:9AC0`, called by either loop's start.
static bool accepts_begin(const Wram* w, const CosimRegs* in);
static int saucer_alloc_cycles(uint16_t record, bool fast);

static bool guard_martian_begin(Wram* scratch, const Rom* rom,
                                const CosimRegs* in) {
  (void)rom;
  if (!accepts_begin(scratch, in) || in->db != MARTIAN_BANK) return false;
  PortCpu c;
  uint16_t record;
  cpu_from(in, &c);
  return martian_begin(scratch, &c, &record);
}

static void shim_martian_begin(Wram* w, const Rom* rom, const CosimRegs* in,
                               CosimRegs* out) {
  (void)rom;
  PortCpu c;
  uint16_t record = 0;
  cpu_from(in, &c);
  martian_begin(w, &c, &record);
  cpu_to(&c, out);
  cosim_cost(saucer_alloc_cycles(record, in->fastrom) +
             cosim_run_cycles_dp(&MARTIAN_RUN_BEGIN, fetch_fast(in),
                                 (in->d & 0xffu) != 0));
}

static const uint32_t MARTIAN_BEGIN_EXITS[] = {MARTIAN_BEGIN_PLAY_PC};

// The two pieces of a pass that fires, which the ROM calls as it goes.
static bool martian_piece_ok(const Wram* w, const CosimRegs* in) {
  return body_ok(in) && in->d >= 0x0100 && in->db == MARTIAN_BANK &&
         wram_r16(w, (uint16_t)(in->d + MARTIAN_DP_RECORD)) < 0x1f00 &&
         wram_r16(w, (uint16_t)(in->d + MARTIAN_DP_PICTURES)) >= 0x8000;
}

// `$81:9C99`.
static bool accepts_martian_show(const Wram* w, const CosimRegs* in) {
  return martian_piece_ok(w, in) && martian_show_supported(w, in->d);
}

static void shim_martian_show(Wram* w, const Rom* rom, const CosimRegs* in,
                              CosimRegs* out) {
  PortCpu c;
  MartianLog log = {0};
  cpu_from(in, &c);
  martian_show_walking(w, rom, &c, &log);
  ret_from_cpu(&c, out);
  MartianBill b = {{0, 0, 0}, 0, &log, in};
  martian_show_bill(&b);
  cosim_cost(cosim_run_cycles_dp(&b.own, fetch_fast(in),
                                 (in->d & 0x00ffu) != 0));
}

// `$81:9981`, with the data bank at `$81`.
static bool supported_martian_shoot(Wram* scratch, const Rom* rom,
                                    const CosimRegs* in) {
  return martian_piece_ok(scratch, in) &&
         martian_shoot_supported(scratch, rom, in->d, in->a);
}

static void shim_martian_shoot(Wram* w, const Rom* rom, const CosimRegs* in,
                               CosimRegs* out) {
  PortCpu c;
  MartianShot shot = {0};
  cpu_from(in, &c);
  martian_shoot(w, rom, &c, &shot);
  cpu_to(&c, out);
  CosimRun run = {0, 0, 0};
  run_add(&run, &MARTIAN_RUN_SHOOT_HEAD, 1);
  if (!shot.fired) {
    run_add(&run, &MARTIAN_RUN_TAKEN, 1);
    run_add(&run, &MARTIAN_RUN_FIRE_COUNT, 1);
  } else {
    run_add(&run, &MARTIAN_RUN_FIRE_SET, 1);
    run_add(&run, &MARTIAN_RUN_PICTURE, 1);
    run_add(&run, &MARTIAN_RUN_FIRE_FLAGS, 1);
    run_add(&run, shot.mirrored ? &MARTIAN_RUN_SHOW_MIRROR
                                : &MARTIAN_RUN_SHOW_PLAIN, 1);
    run_add(&run, &MARTIAN_RUN_TAKEN, 1);
    run_add(&run, &MARTIAN_RUN_FIRE_STORE, 1);
  }
  cosim_cost(cosim_run_cycles_dp(&run, fetch_fast(in),
                                 (in->d & 0x00ffu) != 0));
}

static const uint32_t MARTIAN_SHOOT_EXITS[] = {MARTIAN_SHOOT_SPAWN_PC,
                                               MARTIAN_SHOOT_RTS_PC};

// ---------------------------------------------------------------------------
// The spiders -- see `port/spider.h`
// ---------------------------------------------------------------------------
//
// One entry, a whole pass of the loop, priced the slimes' way. Each run is
// from `tools/cycles816.py --db 83`, branches not taken; a taken branch, a
// `BRA` and nothing else adds 6.
static const CosimRun SPIDER_RUN_ENTER = {142, 8, 1};         // $B299-$B2A0
static const CosimRun SPIDER_RUN_SHOW_CALL = {40, 3, 0};      // $B2A1 JSR $B2D0
static const CosimRun SPIDER_RUN_FATE = {40, 4, 1};           // $B2A4 LDA $20 : BEQ
static const CosimRun SPIDER_RUN_SLEEP = {46, 5, 1};          // $B290 STZ $24 : LDA #$0002
static const CosimRun SPIDER_RUN_RTS = {40, 1, 0};
static const CosimRun SPIDER_RUN_JMP = {18, 3, 0};
static const CosimRun SPIDER_RUN_TAKEN = {6, 0, 0};
static const CosimRun SPIDER_RUN_SHOW_TIMER = {62, 4, 1};     // $B2D0 DEC $1E : BPL
static const CosimRun SPIDER_RUN_SHOW_NEXT = {370, 36, 5};    // $B2D4-$B2F5
static const CosimRun SPIDER_RUN_SHOW_MIRROR = {30, 5, 0};    // $B2F6 ORA : BRA
static const CosimRun SPIDER_RUN_SHOW_PLAIN = {18, 3, 0};     // $B2FB AND
static const CosimRun SPIDER_RUN_SHOW_STORE = {40, 3, 0};     // $B2FE STA $0000,Y
static const CosimRun SPIDER_RUN_SHOW_PUBLISH = {204, 13, 3}; // $B301-$B30D
static const CosimRun SPIDER_RUN_CLEAR_GROUND = {122, 10, 2}; // LDX LDY JSL BCS
static const CosimRun SPIDER_RUN_CLEAR_ACTOR = {150, 12, 3};  // LDA LDX LDY JSL BCS
static const CosimRun SPIDER_RUN_BACK = {436, 42, 6};         // $B3BE-$B3E3
static const CosimRun SPIDER_RUN_TAKE = {56, 4, 2};           // LDA : STA
static const CosimRun SPIDER_RUN_LOOK = {140, 13, 2};         // $B41E-$B42A
static const CosimRun SPIDER_RUN_LOOK_BAND = {30, 5, 0};      // $B42B CMP : BCC
static const CosimRun SPIDER_RUN_LOOK_GONE = {152, 14, 2};    // $B430-$B43D
static const CosimRun SPIDER_RUN_LEAVE = {50, 2, 1};          // $B43E DEC $20
static const CosimRun SPIDER_RUN_TURN = {170, 18, 2};         // $B445-$B456
static const CosimRun SPIDER_RUN_SET_STATE = {86, 6, 1};      // LDA # : STA $1A : RTS
static const CosimRun SPIDER_RUN_JSR = {40, 3, 0};            // $B46B JSR $B41E
static const CosimRun SPIDER_RUN_TRY = {312, 29, 5};          // $B46E-$B486, $B49F-$B4B7
static const CosimRun SPIDER_RUN_MOVE = {152, 9, 4};          // $B487-$B48F, $B4B8-$B4C0
static const CosimRun SPIDER_RUN_AIM = {214, 20, 4};          // $B4C4-$B4D7
static const CosimRun SPIDER_RUN_AIM_PICK = {418, 34, 6};     // $B4DB-$B4FC
static const CosimRun SPIDER_RUN_RUN_HEAD = {62, 4, 1};       // $B4FD DEC $18 : BMI
static const CosimRun SPIDER_RUN_RUN_DRAW = {84, 9, 0};       // $B501-$B509
static const CosimRun SPIDER_RUN_RUN_STEP = {340, 28, 5};     // $B50D-$B524

// The ROM's own instructions in `own`, and what its calls cost in `calls`.
typedef struct {
  CosimRun own;
  int calls;
  const SpiderLog* log;
  const CosimRegs* in;
} SpiderBill;

static void spider_add(SpiderBill* b, const CosimRun* r) {
  run_add(&b->own, r, 1);
}

static void spider_taken(SpiderBill* b) { spider_add(b, &SPIDER_RUN_TAKEN); }

// `$83:B3A6`: is the way clear? True when it was not. Both of its `BCS`s go
// to an `RTS`, and the second to the one on the next line.
static bool spider_clear_bill(SpiderBill* b, const SpiderProbe* p) {
  spider_add(b, &SPIDER_RUN_CLEAR_GROUND);
  b->calls += terrain_enemy_cycles(&p->ground, b->in->fastrom);
  if (p->ground.blocked) {
    spider_taken(b);
  } else {
    spider_add(b, &SPIDER_RUN_CLEAR_ACTOR);
    if (p->someone) spider_taken(b);
  }
  spider_add(b, &SPIDER_RUN_RTS);
  return p->ground.blocked || p->someone;
}

// One axis of a running step: taken unless either test says no.
static void spider_axis_bill(SpiderBill* b, const SpiderProbe* p) {
  spider_add(b, &SPIDER_RUN_CLEAR_GROUND);
  b->calls += terrain_enemy_cycles(&p->ground, b->in->fastrom);
  if (p->ground.blocked) {
    spider_taken(b);
    return;
  }
  spider_add(b, &SPIDER_RUN_CLEAR_ACTOR);
  if (p->someone)
    spider_taken(b);
  else
    spider_add(b, &SPIDER_RUN_TAKE);
}

static void spider_aim_bill(SpiderBill* b) {
  const SpiderLog* log = b->log;
  spider_add(b, &SPIDER_RUN_AIM);
  b->calls += nearest_cycles(&log->aim_nearest, b->in->fastrom);
  if (log->gave_up) {
    spider_add(b, &SPIDER_RUN_JMP);
    spider_add(b, &SPIDER_RUN_SET_STATE);
    return;
  }
  spider_taken(b);
  spider_add(b, &SPIDER_RUN_AIM_PICK);
  b->calls += actor_bearing_cycles(&log->bearing, b->in->fastrom) +
              rng_cycles(log->aim_overflow, b->in->fastrom);
}

static void spider_look_bill(SpiderBill* b) {
  const SpiderLog* log = b->log;
  spider_add(b, &SPIDER_RUN_LOOK);
  b->calls += nearest_cycles(&log->nearest, b->in->fastrom);
  if (log->look == SPIDER_LOOK_NEAR) {
    spider_taken(b);
    spider_add(b, &SPIDER_RUN_JMP);
    spider_aim_bill(b);
    return;
  }
  spider_add(b, &SPIDER_RUN_LOOK_BAND);
  if (log->look == SPIDER_LOOK_MIDDLE) {
    spider_taken(b);
  } else {
    spider_add(b, &SPIDER_RUN_LOOK_GONE);
    b->calls += player_bearing_cycles(&log->players, b->in->fastrom);
    spider_add(b, log->look == SPIDER_LOOK_LEAVE ? &SPIDER_RUN_LEAVE
                                                 : &SPIDER_RUN_TAKEN);
  }
  spider_add(b, &SPIDER_RUN_RTS);
}

// How wandering and feeling end: the step, or a turn.
static void spider_step_bill(SpiderBill* b) {
  spider_add(b, &SPIDER_RUN_TRY);
  if (spider_clear_bill(b, &b->log->ahead)) {
    spider_taken(b);
    spider_add(b, &SPIDER_RUN_JMP);
    spider_add(b, &SPIDER_RUN_TURN);
    spider_add(b, &SPIDER_RUN_SET_STATE);
  } else {
    spider_add(b, &SPIDER_RUN_MOVE);
  }
}

static void spider_state_bill(SpiderBill* b) {
  const SpiderLog* log = b->log;
  switch (log->state) {
    case SPIDER_STATE_WANDER:
      spider_add(b, &SPIDER_RUN_JSR);
      spider_look_bill(b);
      spider_step_bill(b);
      break;
    case SPIDER_STATE_FEEL:
      spider_add(b, &SPIDER_RUN_JSR);
      spider_add(b, &SPIDER_RUN_JSR);
      spider_look_bill(b);
      spider_add(b, &SPIDER_RUN_BACK);
      spider_clear_bill(b, &log->back);
      spider_add(b, log->turned_back ? &SPIDER_RUN_TAKE : &SPIDER_RUN_TAKEN);
      spider_add(b, &SPIDER_RUN_RTS);
      spider_step_bill(b);
      break;
    default:
      spider_add(b, &SPIDER_RUN_RUN_HEAD);
      if (!log->ran) {
        spider_taken(b);
        spider_aim_bill(b);
        break;
      }
      spider_add(b, &SPIDER_RUN_RUN_DRAW);
      b->calls += rng_cycles(log->run_overflow, b->in->fastrom);
      spider_add(b, log->steps == 1 ? &SPIDER_RUN_TAKEN : &SPIDER_RUN_JSR);
      for (int i = 0; i < log->steps; i++) {
        spider_add(b, &SPIDER_RUN_RUN_STEP);
        spider_axis_bill(b, &log->step[i][0]);
        spider_axis_bill(b, &log->step[i][1]);
        spider_add(b, &SPIDER_RUN_RTS);
      }
      break;
  }
}

static void spider_show_bill(SpiderBill* b) {
  const SpiderLog* log = b->log;
  spider_add(b, &SPIDER_RUN_SHOW_TIMER);
  if (log->new_picture) {
    spider_add(b, &SPIDER_RUN_SHOW_NEXT);
    spider_add(b, log->mirrored ? &SPIDER_RUN_SHOW_MIRROR
                                : &SPIDER_RUN_SHOW_PLAIN);
    spider_taken(b);  // the `BCC` round the mirror, or the `BRA` out of it
    spider_add(b, &SPIDER_RUN_SHOW_STORE);
  } else {
    spider_taken(b);
  }
  spider_add(b, &SPIDER_RUN_SHOW_PUBLISH);
}

// The tests put their scratch on page zero, and the tables are read through
// the data bank. So is the record, which has to be in the WRAM bank `$83`
// mirrors.
static bool spider_frame_ok(const Wram* w, const CosimRegs* in) {
  if (!body_ok(in) || in->d < 0x0100 || in->db != SPIDER_BANK) return false;
  return wram_r16(w, (uint16_t)(in->d + SPIDER_DP_RECORD)) < 0x1f00 &&
         spider_frame_supported(w, in->d);
}

// It leaves by the `JSL thread_yield` with the tick count in A, or past the
// test of its fate with that in A.
static void shim_spider_frame(Wram* w, const Rom* rom, const CosimRegs* in,
                              CosimRegs* out) {
  SpiderLog log = {0};
  const bool stays =
      spider_frame(w, rom, in->d, (in->p & PORT_P_C) != 0, &log);

  SpiderBill b = {{0, 0, 0}, 0, &log, in};
  spider_add(&b, &SPIDER_RUN_ENTER);
  spider_state_bill(&b);
  spider_add(&b, &SPIDER_RUN_SHOW_CALL);
  spider_show_bill(&b);
  spider_add(&b, &SPIDER_RUN_FATE);
  if (stays) {
    spider_taken(&b);
    spider_add(&b, &SPIDER_RUN_SLEEP);
  }
  b.calls += at_point_cycles(&log.at_point, in->fastrom);
  cosim_cost(b.calls + cosim_run_cycles_dp(&b.own, fetch_fast(in),
                                           (in->d & 0x00ffu) != 0));

  out->pc = stays ? SPIDER_YIELD_PC : SPIDER_FATE_PC;
  out->a = stays ? SPIDER_YIELD_TICKS
                 : wram_r16(w, (uint16_t)(in->d + SPIDER_DP_FATE));
  out->regs = COSIM_REG_A;
  out->p = (uint8_t)(in->p & ~(PORT_P_N | PORT_P_Z | PORT_P_C | PORT_P_V));
  if (out->a & 0x8000u) out->p |= PORT_P_N;
  if (log.c) out->p |= PORT_P_C;
  if (log.v) out->p |= PORT_P_V;
  out->p_keep = (uint8_t)((log.c_set ? 0 : PORT_P_C) | (log.v_set ? 0 : PORT_P_V));
}

static const uint32_t SPIDER_FRAME_EXITS[] = {SPIDER_YIELD_PC, SPIDER_FATE_PC};

// ---------------------------------------------------------------------------
// The colour fade -- see `port/palfade.h`
// ---------------------------------------------------------------------------
//
// Priced as the spiders are: each run from `tools/cycles816.py`, branches not
// taken, a taken branch and every `BRA` adding 6. The thread's own loop runs
// on its page; the two row routines and the step they call put page zero in D
// and `$7E` in the data bank, so theirs are a second sum that never pays for
// an unaligned page. The colours being faded to are read from the cartridge,
// `--ind=9F:8000`, and the colours on screen from WRAM, `--db=7E`.
static const CosimRun PALFADE_RUN_ROW = {136, 11, 3};         // $ABBD-$ABC7, $ABCA-$ABD4
static const CosimRun PALFADE_RUN_INC = {50, 2, 1};           // $ABC8 INC $0A
static const CosimRun PALFADE_RUN_ADVANCE = {88, 11, 1};      // $ABD7-$ABE1
static const CosimRun PALFADE_RUN_DONE_TEST = {40, 4, 1};     // $ABE2 LDA $0A : BEQ
static const CosimRun PALFADE_RUN_UPLOAD = {136, 15, 1};      // $ABE6-$ABF4
static const CosimRun PALFADE_RUN_STORE = {86, 9, 2};         // $ABF5-$ABFD
static const CosimRun PALFADE_RUN_SOONER = {52, 5, 1};        // $ABFE DEC : STA : BRA
static const CosimRun PALFADE_RUN_SLEEP = {28, 2, 1};         // $ABB7 LDA $0E
static const CosimRun PALFADE_RUN_TAKEN = {6, 0, 0};
static const CosimRun PALFADE_RUN_BG_HEAD = {262, 19, 2};     // $AB19-$AB2B
static const CosimRun PALFADE_RUN_BG_SETUP = {110, 10, 2};    // $AB2C-$AB35
static const CosimRun PALFADE_RUN_BG_COLOUR = {152, 13, 1};   // $AB36-$AB40
static const CosimRun PALFADE_RUN_BG_STORE = {130, 8, 1};     // $AB41-$AB48
static const CosimRun PALFADE_RUN_SPR_HEAD = {342, 24, 4};    // $AB5B-$AB72
static const CosimRun PALFADE_RUN_SPR_COLOUR = {152, 13, 1};  // $AB73-$AB7D
static const CosimRun PALFADE_RUN_SPR_STORE = {90, 5, 1};     // $AB7E-$AB82
static const CosimRun PALFADE_RUN_ROW_NEXT = {64, 6, 1};      // INY INY CPY BCC
static const CosimRun PALFADE_RUN_ROW_TAIL = {40, 4, 1};      // LDA $38 : BEQ
static const CosimRun PALFADE_RUN_ROW_SEC = {24, 3, 0};       // SEC : BRA
static const CosimRun PALFADE_RUN_ROW_CLC = {12, 1, 0};
static const CosimRun PALFADE_RUN_ROW_RET = {126, 4, 0};      // PLB PLD PLB RTS
static const CosimRun PALFADE_RUN_STEP_HEAD = {68, 6, 2};     // $AAB7 STX CMP BEQ
static const CosimRun PALFADE_RUN_STEP_SAME = {52, 2, 0};     // $AB17 CLC RTS
static const CosimRun PALFADE_RUN_STEP_SPLIT = {250, 23, 7};  // $AABD-$AAD3
static const CosimRun PALFADE_RUN_BLUE_TEST = {86, 9, 2};     // $AAD4-$AADC
static const CosimRun PALFADE_RUN_WIDE_TEST = {114, 11, 3};   // $AAE9-$AAF3, $AB00-$AB0A
static const CosimRun PALFADE_RUN_BCS = {12, 2, 0};
static const CosimRun PALFADE_RUN_WIDE_UP = {42, 6, 0};       // CLC ADC BRA
static const CosimRun PALFADE_RUN_WIDE_DOWN = {30, 4, 0};     // SEC SBC
static const CosimRun PALFADE_RUN_RED_UP = {24, 3, 0};        // INC BRA
static const CosimRun PALFADE_RUN_RED_DOWN = {12, 1, 0};      // DEC
static const CosimRun PALFADE_RUN_STEP_TAIL = {108, 6, 2};    // $AB11-$AB16
static const CosimRun PALFADE_RUN_QUEUE_HEAD = {92, 9, 0};    // $80:83AE-$83B6
static const CosimRun PALFADE_RUN_QUEUE_FULL = {76, 2, 0};    // $80:83D3 PLY RTL
static const CosimRun PALFADE_RUN_QUEUE_FIRST = {18, 3, 0};   // $80:83B7 LDX #$0038
static const CosimRun PALFADE_RUN_QUEUE_TEST = {52, 5, 0};    // $80:83BA LDY : BEQ
static const CosimRun PALFADE_RUN_QUEUE_NEXT = {60, 6, 0};    // $80:83BF DEX x4 : BNE
static const CosimRun PALFADE_RUN_QUEUE_STORE = {248, 14, 0}; // $80:83C5-$83D2

#define PALFADE_QUEUE_FIRST_SLOT 0x38
#define PALFADE_QUEUE_SLOT_BYTES 4

// A channel of the colours that moved: its test, and which of three ways out.
static void palfade_channel_bill(CosimRun* zero, const PalfadeChannelWork* c,
                              const CosimRun* test, const CosimRun* up,
                              const CosimRun* down) {
  const int moved = c->kept + c->raised + c->lowered;
  run_add(zero, test, moved);
  run_add(zero, &PALFADE_RUN_TAKEN, c->kept);  // the `BEQ` round both
  run_add(zero, &PALFADE_RUN_BCS, c->raised + c->lowered);
  run_add(zero, up, c->raised);
  run_add(zero, &PALFADE_RUN_TAKEN, c->raised);  // ...its `BRA`
  run_add(zero, &PALFADE_RUN_TAKEN, c->lowered);  // ...or the `BCS`
  run_add(zero, down, c->lowered);
}

// A row routine, the step it calls sixteen times included.
static void palfade_row_bill(CosimRun* zero, const PalfadeRowWork* r,
                          const CosimRun* head, const CosimRun* setup,
                          const CosimRun* colour, const CosimRun* store) {
  run_add(zero, head, 1);
  if (!r->ran) {  // `CPX #$00E0 : BCS` to the `CLC`
    run_add(zero, &PALFADE_RUN_TAKEN, 1);
    run_add(zero, &PALFADE_RUN_ROW_CLC, 1);
    run_add(zero, &PALFADE_RUN_ROW_RET, 1);
    return;
  }
  const int moved = PALFADE_ROW_COLOURS - r->settled;
  if (setup != NULL) run_add(zero, setup, 1);
  run_add(zero, colour, PALFADE_ROW_COLOURS);
  run_add(zero, &PALFADE_RUN_STEP_HEAD, PALFADE_ROW_COLOURS);
  // One already there: the step's `BEQ`, its `CLC : RTS`, the row's `BCC`.
  run_add(zero, &PALFADE_RUN_STEP_SAME, r->settled);
  run_add(zero, &PALFADE_RUN_TAKEN, 2 * r->settled);
  run_add(zero, &PALFADE_RUN_STEP_SPLIT, moved);
  palfade_channel_bill(zero, &r->blue, &PALFADE_RUN_BLUE_TEST, &PALFADE_RUN_WIDE_UP,
                    &PALFADE_RUN_WIDE_DOWN);
  palfade_channel_bill(zero, &r->green, &PALFADE_RUN_WIDE_TEST, &PALFADE_RUN_WIDE_UP,
                    &PALFADE_RUN_WIDE_DOWN);
  palfade_channel_bill(zero, &r->red, &PALFADE_RUN_WIDE_TEST, &PALFADE_RUN_RED_UP,
                    &PALFADE_RUN_RED_DOWN);
  run_add(zero, &PALFADE_RUN_STEP_TAIL, moved);
  run_add(zero, store, moved);
  run_add(zero, &PALFADE_RUN_ROW_NEXT, PALFADE_ROW_COLOURS);
  run_add(zero, &PALFADE_RUN_TAKEN, PALFADE_ROW_COLOURS - 1);
  run_add(zero, &PALFADE_RUN_ROW_TAIL, 1);
  if (moved != 0) {
    run_add(zero, &PALFADE_RUN_ROW_SEC, 1);
    run_add(zero, &PALFADE_RUN_TAKEN, 1);  // its `BRA`
  } else {
    run_add(zero, &PALFADE_RUN_TAKEN, 1);
    run_add(zero, &PALFADE_RUN_ROW_CLC, 1);
  }
  run_add(zero, &PALFADE_RUN_ROW_RET, 1);
}

// `$80:83AE`, by where the job went. The search comes down from slot 14 and
// takes slot 0 without testing it.
static void palfade_queue_bill(CosimRun* zero, int slot) {
  run_add(zero, &PALFADE_RUN_QUEUE_HEAD, 1);
  if (slot < 0) {
    run_add(zero, &PALFADE_RUN_TAKEN, 1);
    run_add(zero, &PALFADE_RUN_QUEUE_FULL, 1);
    return;
  }
  const int busy = (PALFADE_QUEUE_FIRST_SLOT - slot) / PALFADE_QUEUE_SLOT_BYTES;
  run_add(zero, &PALFADE_RUN_QUEUE_FIRST, 1);
  run_add(zero, &PALFADE_RUN_QUEUE_TEST, busy);
  run_add(zero, &PALFADE_RUN_QUEUE_NEXT, busy);
  if (slot != 0) {
    run_add(zero, &PALFADE_RUN_TAKEN, busy);  // each `BNE` back
    run_add(zero, &PALFADE_RUN_QUEUE_TEST, 1);
    run_add(zero, &PALFADE_RUN_TAKEN, 1);  // the `BEQ` out
  } else {
    run_add(zero, &PALFADE_RUN_TAKEN, busy - 1);  // the last `BNE` falls through
  }
  run_add(zero, &PALFADE_RUN_QUEUE_STORE, 1);
}

// The rows put page zero in D themselves, and the queue is reached through
// the data bank.
static bool palfade_frame_ok(const Wram* w, const CosimRegs* in) {
  return body_ok(in) && in->d >= 0x0100 && bank_sees_low_wram(in->db) &&
         palfade_frame_supported(w, in->d);
}

// It leaves by the `JSL thread_yield` with the tick count in A, or at the two
// instructions that end the thread, with the sweep's count of zero in A.
static void shim_palfade_frame(Wram* w, const Rom* rom, const CosimRegs* in,
                            CosimRegs* out) {
  PalfadeLog log = {0};
  const bool stays = palfade_frame(w, rom, in->d, &log);

  CosimRun own = {0, 0, 0}, zero = {0, 0, 0};
  run_add(&own, &PALFADE_RUN_ROW, 2);
  palfade_row_bill(&zero, &log.background, &PALFADE_RUN_BG_HEAD, &PALFADE_RUN_BG_SETUP,
                &PALFADE_RUN_BG_COLOUR, &PALFADE_RUN_BG_STORE);
  palfade_row_bill(&zero, &log.sprites, &PALFADE_RUN_SPR_HEAD, NULL,
                &PALFADE_RUN_SPR_COLOUR, &PALFADE_RUN_SPR_STORE);
  const bool background_moved =
      log.background.ran && log.background.settled < PALFADE_ROW_COLOURS;
  const bool sprites_moved = log.sprites.settled < PALFADE_ROW_COLOURS;
  run_add(&own, background_moved ? &PALFADE_RUN_INC : &PALFADE_RUN_TAKEN, 1);
  run_add(&own, sprites_moved ? &PALFADE_RUN_INC : &PALFADE_RUN_TAKEN, 1);
  run_add(&own, &PALFADE_RUN_ADVANCE, 1);
  if (!log.swept) {
    run_add(&own, &PALFADE_RUN_TAKEN, 1);
  } else {
    run_add(&own, &PALFADE_RUN_DONE_TEST, 1);
    if (log.over) {
      run_add(&own, &PALFADE_RUN_TAKEN, 1);
    } else {
      run_add(&own, &PALFADE_RUN_UPLOAD, 1);
      palfade_queue_bill(&zero, log.queue_slot);
    }
  }
  if (stays) {
    run_add(&own, &PALFADE_RUN_STORE, 1);
    if (log.sooner) {
      run_add(&own, &PALFADE_RUN_SOONER, 1);
    }
    run_add(&own, &PALFADE_RUN_TAKEN, 1);  // the `BCC`, or the `BRA`
    run_add(&own, &PALFADE_RUN_SLEEP, 1);
  }
  cosim_cost(cosim_run_cycles_dp(&zero, fetch_fast(in), false) +
             cosim_run_cycles_dp(&own, fetch_fast(in),
                                 (in->d & 0x00ffu) != 0));

  out->pc = stays ? PALFADE_YIELD_PC : PALFADE_OVER_PC;
  out->a = stays ? log.ticks : 0;
  out->regs = COSIM_REG_A;
  out->p = (uint8_t)(in->p & ~(PORT_P_N | PORT_P_Z | PORT_P_C | PORT_P_V));
  if (out->a & 0x8000u) out->p |= PORT_P_N;
  if (out->a == 0) out->p |= PORT_P_Z;
  if (log.c) out->p |= PORT_P_C;
  if (log.v) out->p |= PORT_P_V;
}

static const uint32_t PALFADE_FRAME_EXITS[] = {PALFADE_YIELD_PC, PALFADE_OVER_PC};

// ---------------------------------------------------------------------------
// A player stuck fast -- see `port/stuck.h`
// ---------------------------------------------------------------------------
//
// Each run is from `tools/cycles816.py --db=80`, branches not taken, and a
// taken branch adds 6. The handler calls nothing, so the sum is the price.
static const CosimRun STUCK_RUN_HEAD = {40, 4, 1};       // $D468 LDA $52 : BPL
static const CosimRun STUCK_RUN_HURT = {92, 10, 2};      // $D46C-$D475
static const CosimRun STUCK_RUN_SHOW = {442, 41, 6};     // $D476-$D49C
static const CosimRun STUCK_RUN_WAS = {58, 7, 1};        // LDA $24 : CMP : BNE
static const CosimRun STUCK_RUN_INC = {50, 2, 1};        // INC $5A
static const CosimRun STUCK_RUN_LEFT = {70, 8, 0};       // $D4A6-$D4AD
static const CosimRun STUCK_RUN_COUNT = {58, 7, 1};      // $D4B7-$D4BD
static const CosimRun STUCK_RUN_FREE = {46, 5, 1};       // $D4BE LDA #1 : STA $56
static const CosimRun STUCK_RUN_LATCH = {148, 12, 2};    // $D4C3-$D4CE
static const CosimRun STUCK_RUN_FACING = {28, 2, 1};     // $D4CF STA $26
static const CosimRun STUCK_RUN_TIMER = {40, 4, 1};      // $D4D1 LDA $16 : BEQ
static const CosimRun STUCK_RUN_DEC = {50, 2, 1};        // $D4D5 DEC $16
static const CosimRun STUCK_RUN_LAST = {40, 4, 1};       // $D4D7 LDA $56 : BEQ
static const CosimRun STUCK_RUN_COUNTDOWN = {62, 4, 1};  // $D4DB DEC $56 : BNE
// The frame it ends on: `STZ $72 : JMP $DC70`, and there `JSR $F3A5`, that
// routine with its `RTS`, and `STZ $70`.
static const CosimRun STUCK_RUN_FREED = {46 + 68 + 228, 5 + 5 + 15, 3};
static const CosimRun STUCK_RUN_RTS = {40, 1, 0};
static const CosimRun STUCK_RUN_TAKEN = {6, 0, 0};

static void stuck_bill(CosimRun* own, const StuckLog* log) {
  run_add(own, &STUCK_RUN_HEAD, 1);
  run_add(own, log->hurt ? &STUCK_RUN_HURT : &STUCK_RUN_TAKEN, 1);
  run_add(own, &STUCK_RUN_SHOW, 1);
  if (log->held_right) {
    run_add(own, &STUCK_RUN_WAS, 1);
    run_add(own, log->shook ? &STUCK_RUN_INC : &STUCK_RUN_TAKEN, 1);
  } else {
    run_add(own, &STUCK_RUN_TAKEN, 1);
  }
  run_add(own, &STUCK_RUN_LEFT, 1);
  if (log->held_left) {
    run_add(own, &STUCK_RUN_WAS, 1);
    run_add(own, log->shook ? &STUCK_RUN_INC : &STUCK_RUN_TAKEN, 1);
  } else {
    run_add(own, &STUCK_RUN_TAKEN, 1);
  }
  run_add(own, &STUCK_RUN_COUNT, 1);
  run_add(own, log->third_shake ? &STUCK_RUN_FREE : &STUCK_RUN_TAKEN, 1);
  run_add(own, &STUCK_RUN_LATCH, 1);
  run_add(own, log->turned ? &STUCK_RUN_FACING : &STUCK_RUN_TAKEN, 1);
  run_add(own, &STUCK_RUN_TIMER, 1);
  run_add(own, log->timer_ran ? &STUCK_RUN_DEC : &STUCK_RUN_TAKEN, 1);
  run_add(own, &STUCK_RUN_LAST, 1);
  if (log->counting) run_add(own, &STUCK_RUN_COUNTDOWN, 1);
  // The `BEQ`, or the `BNE`, taken on every frame but the last.
  run_add(own, log->freed ? &STUCK_RUN_FREED : &STUCK_RUN_TAKEN, 1);
  run_add(own, &STUCK_RUN_RTS, 1);
}

// The pad and the pictures are read through the data bank, and both records
// have to be in the WRAM that bank mirrors.
static bool stuck_ok(const Wram* w, const CosimRegs* in) {
  if (!body_ok(in) || in->db != STUCK_BANK) return false;
  return wram_r16(w, (uint16_t)(in->d + STUCK_DP_RECORD)) < 0x1f00 &&
         wram_r16(w, (uint16_t)(in->d + STUCK_DP_COVER)) < 0x1f00 &&
         wram_r16(w, (uint16_t)(in->d + STUCK_DP_PLAYER)) < 4 &&
         stuck_supported(w, in->d);
}

static void shim_stuck(Wram* w, const Rom* rom, const CosimRegs* in,
                       CosimRegs* out) {
  StuckLog log = {0};
  stuck(w, rom, in->d, &log);

  CosimRun own = {0, 0, 0};
  stuck_bill(&own, &log);
  cosim_cost(cosim_run_cycles_dp(&own, fetch_fast(in), (in->d & 0x00ffu) != 0));

  out->a = log.a;
  out->x = log.x;
  out->y = log.y;
  out->n = log.n;
  out->z = log.z;
  out->c = log.c;
  out->flags = COSIM_FLAG_N | COSIM_FLAG_Z | COSIM_FLAG_C;
}

// ---------------------------------------------------------------------------
// The big figure's colours -- see `port/figure_colours.h`
// ---------------------------------------------------------------------------
//
// Each run is from `tools/cycles816.py`, branches not taken, and a taken
// branch adds 6. The loop's `LDA $0000,Y` reads the cartridge, so its two
// bytes are in the count of those FastROM makes cheap.
static const CosimRun FIGURE_COLOURS_RUN_HEAD = {132, 11, 0};  // $8138-$8142
static const CosimRun FIGURE_COLOURS_RUN_LOOP = {194, 22, 0};  // $8143-$8156
static const CosimRun FIGURE_COLOURS_RUN_TAIL = {116, 11, 0};  // $8157-$8161
static const CosimRun FIGURE_COLOURS_RUN_RTL = {42, 1, 0};
static const CosimRun QUEUE_B_RUN_HEAD = {92, 9, 0};    // $80:8418-$8420
static const CosimRun QUEUE_B_RUN_FULL = {76, 2, 0};    // $80:843B PLY RTL
static const CosimRun QUEUE_B_RUN_FIRST = {18, 3, 0};   // $80:8421 LDX #$001C
static const CosimRun QUEUE_B_RUN_TEST = {52, 5, 0};    // $80:8424 LDY : BEQ
static const CosimRun QUEUE_B_RUN_NEXT = {60, 6, 0};    // $80:8429 DEX x4 : BNE
static const CosimRun QUEUE_B_RUN_STORE = {224, 12, 0}; // $80:842F-$843A
static const CosimRun QUEUE_RUN_TAKEN = {6, 0, 0};

#define QUEUE_B_FIRST_SLOT 0x1c
#define QUEUE_SLOT_BYTES 4

// `$80:8418`, by where the job went. The search comes down from slot 7 and
// takes slot 0 without testing it.
static void queue_b_bill(CosimRun* run, int slot) {
  run_add(run, &QUEUE_B_RUN_HEAD, 1);
  if (slot < 0) {
    run_add(run, &QUEUE_RUN_TAKEN, 1);
    run_add(run, &QUEUE_B_RUN_FULL, 1);
    return;
  }
  const int busy = (QUEUE_B_FIRST_SLOT - slot) / QUEUE_SLOT_BYTES;
  run_add(run, &QUEUE_B_RUN_FIRST, 1);
  run_add(run, &QUEUE_B_RUN_TEST, busy);
  run_add(run, &QUEUE_B_RUN_NEXT, busy);
  if (slot != 0) {
    run_add(run, &QUEUE_RUN_TAKEN, busy);  // each `BNE` back
    run_add(run, &QUEUE_B_RUN_TEST, 1);
    run_add(run, &QUEUE_RUN_TAKEN, 1);  // the `BEQ` out
  } else {
    run_add(run, &QUEUE_RUN_TAKEN, busy - 1);  // the last `BNE` falls through
  }
  run_add(run, &QUEUE_B_RUN_STORE, 1);
}

static int figure_colours_cycles(int slot, bool fast) {
  CosimRun run = {0, 0, 0};
  run_add(&run, &FIGURE_COLOURS_RUN_HEAD, 1);
  run_add(&run, &FIGURE_COLOURS_RUN_LOOP, FIGURE_COLOURS_COUNT);
  run_add(&run, &QUEUE_RUN_TAKEN, FIGURE_COLOURS_COUNT - 1);
  run_add(&run, &FIGURE_COLOURS_RUN_TAIL, 1);
  queue_b_bill(&run, slot);
  run_add(&run, &FIGURE_COLOURS_RUN_RTL, 1);
  return cosim_run_cycles_dp(&run, fast, false);
}

// The colours are read through the bank in Y, and the queue through the
// caller's data bank.
static bool figure_colours_ok(const Wram* w, const CosimRegs* in) {
  (void)w;
  return wide(in) && low_stack(in) && bank_sees_low_wram(in->db) &&
         figure_colours_supported(in->a, (uint8_t)in->y);
}

static void shim_figure_colours_set(Wram* w, const Rom* rom,
                                    const CosimRegs* in, CosimRegs* out) {
  // What `vbl_queue_b_add` leaves in Y: the last word its search read.
  const uint16_t probe = wram_r16(w, W_VBL_QUEUE_B + 4);
  const int slot = figure_colours_set(w, rom, in->a, (uint8_t)in->y);
  cosim_cost(figure_colours_cycles(slot, fetch_fast(in)));

  if (slot < 0) {  // full: the job's address and bank, as they were loaded
    out->a = FIGURE_COLOURS_JOB;
    out->x = 2 * FIGURE_COLOURS_COUNT;
    out->y = FIGURE_COLOURS_JOB_BANK;
    queue_flags(w, W_VBL_QUEUE_B_COUNT, FIGURE_COLOURS_JOB_BANK, false, out);
    return;
  }
  out->a = FIGURE_COLOURS_JOB_BANK;
  out->x = (uint16_t)slot;
  out->y = slot == 0 ? probe : 0;
  queue_flags(w, W_VBL_QUEUE_B_COUNT, FIGURE_COLOURS_JOB_BANK, true, out);
}

