static const CosimRun FISHMAN_RUN_SWEEP_LIST = {58, 6, 0};  // $E33C STA : LDA #$E3A0
static const CosimRun FISHMAN_RUN_BLOW_DRESS = {638, 51, 3};  // $E3E0-$E412
static const CosimRun FISHMAN_RUN_SWEEP_SET = {138, 12, 3};  // $E349-$E354
static const CosimRun FISHMAN_RUN_DIVE_BEGIN = {426, 42, 5};  // $DB63-$DB8A
static const CosimRun FISHMAN_RUN_SPLASH = {150, 16, 2};  // $DBCD-$DBDC
static const CosimRun FISHMAN_RUN_SPLASH_DRESS = {402, 38, 4};  // $DBE1-$DC06, the JMP too
// A leap or a dive, where its sleep comes back. The two have the same
// instructions as far as the longer gap.
static const CosimRun FISHMAN_RUN_WAIT = {84, 8, 0};  // $E06A and $DB04 JSL : AND #$0007 : INC
static const CosimRun FISHMAN_RUN_WAKE_BACK = {52, 2, 0};  // $E076 CLC : RTS
static const CosimRun FISHMAN_RUN_GAP_X_HEAD = {264, 22, 6};  // $E07C-$E091 and $DB10-$DB25, to the BPL
static const CosimRun FISHMAN_RUN_GAP_X_TAIL = {86, 9, 2};  // $E099-$E0A1 and $DB2D-$DB35, to the branch
static const CosimRun FISHMAN_RUN_GAP_Y_HEAD = {98, 10, 2};  // $E0A2-$E0AB and $DB39-$DB42
static const CosimRun FISHMAN_RUN_GAP_Y_TAIL = {96, 8, 3};  // $E0B3-$E0BA and $DB4A-$DB51
static const CosimRun FISHMAN_RUN_GAP_LONGER = {28, 2, 1};  // LDA $36
static const CosimRun FISHMAN_RUN_LEAP_SPAN = {154, 13, 4};  // $E0BD-$E0C9, the JMP too
static const CosimRun FISHMAN_RUN_LEAP_FORM = {174, 18, 3};  // $E0CB-$E0DA, to the BMI
static const CosimRun FISHMAN_RUN_LEAP_FACE_ON = {52, 5, 0};  // $E0DB ORA : BRA, less its 6
static const CosimRun FISHMAN_RUN_LEAP_FACE_OFF = {40, 3, 0};  // $E0E0 AND
static const CosimRun FISHMAN_RUN_LEAP_DRESS = {670, 61, 4};  // $E0E3-$E11F, the RTS too
static const CosimRun FISHMAN_RUN_DIVE_SPAN = {124, 9, 4};  // $DB54-$DB5C
static const CosimRun FISHMAN_RUN_STALK_STEP = {504, 42, 8};  // $DA46-$DA6B, the JSR too
static const CosimRun FISHMAN_RUN_WALK_GROUND = {122, 10, 2};  // LDX : LDY : JSL : BCC
static const CosimRun FISHMAN_RUN_WALK_SEEK = {108 + 6, 9, 2};  // LDX : LDY : JSR $DA85 : BRA
static const CosimRun FISHMAN_RUN_WALK_TAKE = {56, 4, 2};  // LDA : STA
static const CosimRun FISHMAN_RUN_SEEK_HEAD = {250, 21, 2};  // $DA85-$DA99, to CPY #$0018 : BCC
static const CosimRun FISHMAN_RUN_SEEK_BACK = {86, 8, 2};  // $DA9A LDA : EOR : INC : STA
static const CosimRun FISHMAN_RUN_SEEK_SPOT = {388, 33, 5};  // $DAA2-$DABE, to AND #$0100 : BEQ
static const CosimRun FISHMAN_RUN_SEEK_BELOW = {182, 18, 2};  // $DABF-$DAD0, the same
static const CosimRun FISHMAN_RUN_SEEK_EDGE = {122, 10, 2};  // $DAD1 LDX : LDY : JSL : BCS
static const CosimRun FISHMAN_RUN_TAKEN = {6, 0, 0};

static int wander_cycles(const WanderWork* k, const CosimRegs* in);

// The ROM's own instructions on the thread's page in `own`, those of its two
// tile tests in `zero`, which install page zero, and what its calls cost in
// `calls`. The three counts say how many of each the bill has come to.
typedef struct {
  CosimRun own;
  CosimRun zero;
  int calls;
  const FishmanLog* log;
  const CosimRegs* in;
  int slides, player_asks, bearings;
} FishmanBill;

static void fishman_add(FishmanBill* b, const CosimRun* r) {
  run_add(&b->own, r, 1);
}

static void fishman_taken(FishmanBill* b) {
  fishman_add(b, &FISHMAN_RUN_TAKEN);
}

// `$81:DC24` or `$81:E1D6`: each tile to its branch, which the first that
// fails takes to the other `PLD`.
static void fishman_tiles_bill(FishmanBill* b, const FishmanTiles* t,
                               const CosimRun* head,
                               const CosimRun* const* tiles) {
  run_add(&b->zero, head, 1);
  for (int i = 0; i < t->tiles; i++) run_add(&b->zero, tiles[i], 1);
  if (!t->all) run_add(&b->zero, &FISHMAN_RUN_TAKEN, 1);
  run_add(&b->zero, &FISHMAN_RUN_WATER_WET, 1);
}

static void fishman_water_bill(FishmanBill* b, const FishmanTiles* t) {
  static const CosimRun* const TILES[] = {
      &FISHMAN_RUN_WATER_TILE_1, &FISHMAN_RUN_WATER_TILE_2,
      &FISHMAN_RUN_WATER_TILE_3, &FISHMAN_RUN_WATER_TILE_4,
      &FISHMAN_RUN_WATER_TILE_5, &FISHMAN_RUN_WATER_TILE_6};
  fishman_tiles_bill(b, t, &FISHMAN_RUN_WATER_HEAD, TILES);
}

static void fishman_landing_bill(FishmanBill* b, const FishmanTiles* t) {
  static const CosimRun* const TILES[] = {
      &FISHMAN_RUN_LAND_TILE_1, &FISHMAN_RUN_LAND_TILE_2,
      &FISHMAN_RUN_LAND_TILE_3, &FISHMAN_RUN_LAND_TILE_4,
      &FISHMAN_RUN_LAND_TILE_5, &FISHMAN_RUN_LAND_TILE_6};
  fishman_tiles_bill(b, t, &FISHMAN_RUN_LAND_HEAD, TILES);
}

// May it swim there: the water, and then whoever is there. True when neither
// branch out was taken.
static bool fishman_probe_bill(FishmanBill* b, const FishmanProbe* p) {
  fishman_add(b, &FISHMAN_RUN_WATER_ASK);
  fishman_water_bill(b, &p->water);
  if (!p->water.all) {
    fishman_taken(b);
    return false;
  }
  fishman_add(b, &FISHMAN_RUN_ACTOR_ASK);
  if (p->someone) {
    fishman_taken(b);
    return false;
  }
  return true;
}

// The players asked after. True when neither is near, and the `BNE` falls
// through.
static bool fishman_players_bill(FishmanBill* b) {
  const PlayerPickRegs* r = &b->log->players[b->player_asks++];
  fishman_add(b, &FISHMAN_RUN_PLAYERS);
  b->calls += player_bearing_cycles(r, b->in->fastrom);
  if (r->a != 0) fishman_taken(b);
  return r->a == 0;
}

// `$81:DD0B`, its `RTS` too. True when it was stuck.
static bool fishman_slide_bill(FishmanBill* b) {
  const FishmanSlide* k = &b->log->slide[b->slides++];
  fishman_add(b, &FISHMAN_RUN_SLIDE_HEAD);
  for (int axis = 0; axis < 2; axis++) {
    if (axis == 1) fishman_add(b, &FISHMAN_RUN_SLIDE_MID);
    if (!k->asked[axis])
      fishman_taken(b);
    else if (fishman_probe_bill(b, &k->axis[axis]))
      fishman_add(b, &FISHMAN_RUN_SLIDE_TAKE);
  }
  fishman_add(b, &FISHMAN_RUN_SLIDE_TAIL);
  if (!k->stuck) fishman_taken(b);
  fishman_add(b, &FISHMAN_RUN_SLIDE_ANSWER);
  return k->stuck;
}

// `$81:DD57`, its `RTS` too.
static void fishman_look_bill(FishmanBill* b) {
  fishman_add(b, &FISHMAN_RUN_LOOK_HEAD);
  if (b->log->look == FISHMAN_LOOK_NEAR) {
    fishman_taken(b);
    fishman_add(b, &FISHMAN_RUN_LOOK_NEAR);
    fishman_add(b, &FISHMAN_RUN_SET_STATE);
    return;
  }
  fishman_add(b, &FISHMAN_RUN_BAND);
  if (b->log->look == FISHMAN_LOOK_WITHIN)
    fishman_taken(b);
  else if (fishman_players_bill(b))
    fishman_add(b, &FISHMAN_RUN_LEAVE);
  fishman_add(b, &FISHMAN_RUN_RTS);
}

// `$81:E007`. When it does not leap, its `RTS` too: every way out is a
// branch taken to it. When it does, as far as its sleep.
static void fishman_leap_bill(FishmanBill* b) {
  const FishmanLog* log = b->log;
  fishman_add(b, &FISHMAN_RUN_LEAP_DRAW);
  if (log->leap != FISHMAN_LEAP_NO_DRAW) {
    fishman_add(b, &FISHMAN_RUN_LEAP_NEAR);
    if (log->leap != FISHMAN_LEAP_NOBODY) {
      fishman_add(b, &FISHMAN_RUN_LEAP_SPOT);
      b->calls += bounds_cycles(log->leap_edge, b->in->fastrom);
      if (log->leap != FISHMAN_LEAP_OFF_LEVEL) {
        fishman_add(b, &FISHMAN_RUN_LEAP_LAND);
        fishman_landing_bill(b, &log->landing);
        if (log->leap != FISHMAN_LEAP_NO_LANDING)
          fishman_add(b, &FISHMAN_RUN_ACTOR_ASK);
      }
    }
  }
  if (log->leap == FISHMAN_LEAP_LEAPS) {
    fishman_add(b, &FISHMAN_RUN_WAIT);
    return;
  }
  fishman_taken(b);
  fishman_add(b, &FISHMAN_RUN_RTS);
}

// The `JSR` to the draw for a leap, and the `BCC` after it. False when it
// is to leap, and the pass stops at its sleep.
static bool fishman_ask_leap_bill(FishmanBill* b) {
  fishman_add(b, &FISHMAN_RUN_JSR);
  fishman_leap_bill(b);
  if (b->log->leap == FISHMAN_LEAP_LEAPS) return false;
  fishman_add(b, &FISHMAN_RUN_BRANCH);
  return true;
}

static void fishman_ask_look_about_bill(FishmanBill* b) {
  fishman_add(b, &FISHMAN_RUN_JSR);
  fishman_add(b, &FISHMAN_RUN_LOOK_ABOUT);
  fishman_add(b, &FISHMAN_RUN_RTS);
}

// The step the way it faces. True when it moved, and the body goes on.
static bool fishman_swim_on_bill(FishmanBill* b) {
  fishman_add(b, &FISHMAN_RUN_TRY);
  fishman_add(b, &FISHMAN_RUN_JSR);
  const bool clear = fishman_probe_bill(b, &b->log->ahead);
  fishman_add(b, &FISHMAN_RUN_RTS);
  fishman_add(b, &FISHMAN_RUN_BRANCH);
  if (!clear) {
    fishman_taken(b);
    fishman_add(b, &FISHMAN_RUN_JMP);
    fishman_add(b, &FISHMAN_RUN_TURN_AT_WALL);
    fishman_add(b, &FISHMAN_RUN_SET_STATE);
    return false;
  }
  fishman_add(b, &FISHMAN_RUN_COMMIT);
  return true;
}

static void fishman_swim_bill(FishmanBill* b) {
  fishman_add(b, &FISHMAN_RUN_JSR);
  fishman_look_bill(b);
  fishman_ask_look_about_bill(b);
  if (!fishman_ask_leap_bill(b)) return;
  if (fishman_swim_on_bill(b)) fishman_add(b, &FISHMAN_RUN_RTS);
}

static void fishman_swim_turned_bill(FishmanBill* b) {
  fishman_ask_look_about_bill(b);
  if (!fishman_ask_leap_bill(b)) return;
  fishman_add(b, &FISHMAN_RUN_JSR);
  fishman_add(b, &FISHMAN_RUN_OPENING_HEAD);
  if (fishman_probe_bill(b, &b->log->opening))
    fishman_add(b, &FISHMAN_RUN_OPENING_TAKE);
  fishman_add(b, &FISHMAN_RUN_RTS);
  if (!fishman_swim_on_bill(b)) return;
  fishman_add(b, &FISHMAN_RUN_JSR);
  fishman_look_bill(b);
  fishman_add(b, &FISHMAN_RUN_RTS);
}

static void fishman_close_in_bill(FishmanBill* b) {
  const FishmanLog* log = b->log;
  const bool fast = b->in->fastrom;
  if (!fishman_ask_leap_bill(b)) return;
  fishman_add(b, &FISHMAN_RUN_CLOSE_HEAD);
  if (log->range == FISHMAN_RANGE_TOUCHING) {
    fishman_taken(b);
    fishman_add(b, &FISHMAN_RUN_LOOK_NEAR);
    fishman_add(b, &FISHMAN_RUN_SET_STATE);
    return;
  }
  fishman_add(b, &FISHMAN_RUN_BAND);
  if (log->range == FISHMAN_RANGE_FAR) {
    if (fishman_players_bill(b)) {
      fishman_add(b, &FISHMAN_RUN_LEAVE);
      fishman_add(b, &FISHMAN_RUN_RTS);
    } else {
      fishman_add(b, &FISHMAN_RUN_JMP);
      fishman_add(b, &FISHMAN_RUN_SET_STATE);
    }
    return;
  }
  fishman_taken(b);
  fishman_add(b, &FISHMAN_RUN_CLOSE_DRAW);
  fishman_add(b, log->close_steps == 2 ? &FISHMAN_RUN_JSR : &FISHMAN_RUN_TAKEN);
  for (int i = 0; i < log->close_steps; i++) {
    fishman_add(b, &FISHMAN_RUN_CLOSE_STEP);
    b->calls += actor_snap_cycles(&log->snap[b->bearings], fast) +
                actor_bearing_cycles(&log->bearing[b->bearings], fast);
    b->bearings++;
    fishman_add(b, &FISHMAN_RUN_JSR);
    fishman_slide_bill(b);
    fishman_add(b, &FISHMAN_RUN_RTS);
  }
}

static void fishman_patrol_bill(FishmanBill* b) {
  const FishmanLog* log = b->log;
  fishman_add(b, &FISHMAN_RUN_TRY);
  fishman_add(b, &FISHMAN_RUN_JSR);
  const bool stuck = fishman_slide_bill(b);
  fishman_add(b, &FISHMAN_RUN_BRANCH);
  if (stuck) {
    fishman_add(b, &FISHMAN_RUN_REVERSE);
    fishman_add(b, log->reversed_wrapped ? &FISHMAN_RUN_REVERSE_WRAP
                                         : &FISHMAN_RUN_TAKEN);
    fishman_add(b, &FISHMAN_RUN_REVERSE_STORE);
  } else {
    fishman_taken(b);
  }
  if (!fishman_ask_leap_bill(b)) return;
  fishman_add(b, &FISHMAN_RUN_PATROL_NEAR);
  if (log->patrol == FISHMAN_PATROL_TOUCHING) {
    fishman_taken(b);
    fishman_add(b, &FISHMAN_RUN_JMP);
    fishman_add(b, &FISHMAN_RUN_SET_STATE);
    return;
  }
  fishman_add(b, &FISHMAN_RUN_PATROL_GAP_X);
  fishman_add(b, log->gap_negative[0] ? &FISHMAN_RUN_NEGATE : &FISHMAN_RUN_TAKEN);
  fishman_add(b, &FISHMAN_RUN_BAND);
  if (log->patrol != FISHMAN_PATROL_IN_COLUMN) {
    fishman_add(b, &FISHMAN_RUN_PATROL_GAP_Y);
    fishman_add(b,
                log->gap_negative[1] ? &FISHMAN_RUN_NEGATE : &FISHMAN_RUN_TAKEN);
    fishman_add(b, &FISHMAN_RUN_BAND);
  }
  if (log->patrol != FISHMAN_PATROL_APART) {
    fishman_taken(b);
    fishman_add(b, &FISHMAN_RUN_JMP);
    fishman_add(b, &FISHMAN_RUN_LINE_UP_SET);
    return;
  }
  if (fishman_players_bill(b)) fishman_add(b, &FISHMAN_RUN_LEAVE);
  fishman_add(b, &FISHMAN_RUN_RTS);
}

static void fishman_line_up_bill(FishmanBill* b) {
  const FishmanLog* log = b->log;
  fishman_add(b, &FISHMAN_RUN_LINE_HEAD);
  fishman_add(b, log->line_steps == 2 ? &FISHMAN_RUN_JSR : &FISHMAN_RUN_TAKEN);
  for (int i = 0; i < log->line_steps; i++) {
    const FishmanLineStep* k = &log->line[i];
    fishman_add(b, &FISHMAN_RUN_LINE_GAP);
    fishman_add(b, k->negative ? &FISHMAN_RUN_LINE_NEGATE : &FISHMAN_RUN_TAKEN);
    fishman_add(b, &FISHMAN_RUN_BAND);
    if (k->arrived) {
      fishman_taken(b);
    } else {
      fishman_add(b, &FISHMAN_RUN_LINE_STEP);
      fishman_add(b, &FISHMAN_RUN_JSR);
      const bool stuck = fishman_slide_bill(b);
      fishman_add(b, &FISHMAN_RUN_BRANCH);
      if (!stuck) {
        fishman_taken(b);
        fishman_add(b, &FISHMAN_RUN_RTS);
        continue;
      }
    }
    fishman_add(b, &FISHMAN_RUN_LINE_DONE);
    fishman_add(b, &FISHMAN_RUN_JSR);
    fishman_add(b, &FISHMAN_RUN_PATROL_AGAIN);
    if (fishman_players_bill(b)) {
      fishman_add(b, &FISHMAN_RUN_LEAVE);
      fishman_add(b, &FISHMAN_RUN_BRANCH);  // a `BRA`
      fishman_taken(b);
    }
    fishman_add(b, &FISHMAN_RUN_RTS);
    fishman_add(b, &FISHMAN_RUN_RTS);
  }
}

// One axis of `$81:E1A3`: the test once more than it stepped, and that last
// one taken.
static void fishman_glide_bill(FishmanBill* b, int steps) {
  run_add(&b->own, &FISHMAN_RUN_GLIDE_TEST, steps + 1);
  run_add(&b->own, &FISHMAN_RUN_GLIDE_STEP, steps);
  run_add(&b->own, &FISHMAN_RUN_TAKEN, steps + 1);
}

static void fishman_fly_bill(FishmanBill* b) {
  const FishmanLog* log = b->log;
  fishman_add(b, &FISHMAN_RUN_JSR);
  fishman_add(b, &FISHMAN_RUN_RISE_HEAD);
  fishman_add(b, log->falling ? &FISHMAN_RUN_RISE_FALLING : &FISHMAN_RUN_TAKEN);
  fishman_add(b, &FISHMAN_RUN_RISE_TAIL);
  fishman_add(b, &FISHMAN_RUN_JSR);
  fishman_add(b, &FISHMAN_RUN_GLIDE_X_HEAD);
  fishman_glide_bill(b, log->glide_steps[0]);
  fishman_add(b, &FISHMAN_RUN_GLIDE_X_TAIL);
  fishman_glide_bill(b, log->glide_steps[1]);
  fishman_add(b, &FISHMAN_RUN_GLIDE_Y_TAIL);
  fishman_add(b, &FISHMAN_RUN_FLIGHT_PLACE);
  if (log->flight == FISHMAN_FLIGHT_DOWN) {
    fishman_taken(b);
  } else {
    fishman_add(b, &FISHMAN_RUN_BRANCH);
    if (log->flight == FISHMAN_FLIGHT_UP) {
      fishman_add(b, &FISHMAN_RUN_RTS);
      return;
    }
    fishman_taken(b);
    fishman_add(b, &FISHMAN_RUN_FLIGHT_FLOOR);
  }
  fishman_add(b, &FISHMAN_RUN_JMP);
  fishman_add(b, &FISHMAN_RUN_SET_STATE);
}

// `$81:E309`, its `RTS` too: it sweeps from its next pass, unless the one
// that comes ashore draws otherwise.
static void fishman_sweep_set_bill(FishmanBill* b) {
  const FishmanLog* log = b->log;
  fishman_add(b, &FISHMAN_RUN_LURK_SET);
  if (!log->sweep_drawn) {
    fishman_taken(b);
    fishman_add(b, &FISHMAN_RUN_RTS);
    return;
  }
  fishman_add(b, &FISHMAN_RUN_SWEEP_DRAW);
  if (!log->sweep_off) {
    fishman_add(b, &FISHMAN_RUN_RTS);
    return;
  }
  fishman_taken(b);
  fishman_add(b, &FISHMAN_RUN_SWEEP_AFTER);
  fishman_taken(b);
  fishman_add(b, &FISHMAN_RUN_JMP);
  fishman_add(b, &FISHMAN_RUN_SET_STATE);
}

static void fishman_land_bill(FishmanBill* b) {
  fishman_add(b, &FISHMAN_RUN_LANDED_HEAD);
  if (b->log->ashore) {
    fishman_taken(b);
    fishman_add(b, &FISHMAN_RUN_JMP);
    fishman_add(b, &FISHMAN_RUN_ASHORE);
    fishman_add(b, &FISHMAN_RUN_SET_STATE);
    return;
  }
  fishman_add(b, &FISHMAN_RUN_JMP);
  fishman_sweep_set_bill(b);
}

// `$81:DA85`, its `RTS` too, when it does not dive: every way back is a
// branch taken to the `SEC`.
static void fishman_seek_bill(FishmanBill* b, const FishmanSeek* k) {
  const bool fast = b->in->fastrom;
  fishman_add(b, &FISHMAN_RUN_SEEK_HEAD);
  fishman_add(b, k->back ? &FISHMAN_RUN_SEEK_BACK : &FISHMAN_RUN_TAKEN);
  fishman_add(b, &FISHMAN_RUN_SEEK_SPOT);
  if (k->tiles == 2) fishman_add(b, &FISHMAN_RUN_SEEK_BELOW);
  b->calls += k->tiles * cosim_run_cycles(&TILE_ATTRS_RUN, fast);
  if (k->edge_asked) {
    fishman_add(b, &FISHMAN_RUN_SEEK_EDGE);
    b->calls += bounds_cycles(k->edge, fast);
  }
  fishman_taken(b);
  fishman_add(b, &FISHMAN_RUN_SLIDE_ANSWER);
}

// `$81:D8B6`, its `RTS` too.
static void fishman_walk_bill(FishmanBill* b) {
  const bool fast = b->in->fastrom;
  for (int axis = 0; axis < 2; axis++) {
    const FishmanLandProbe* k = &b->log->land[axis];
    fishman_add(b, &FISHMAN_RUN_WALK_GROUND);
    b->calls += terrain_enemy_cycles(&k->ground, fast);
    if (k->ground.blocked) {
      fishman_add(b, &FISHMAN_RUN_WALK_SEEK);
      fishman_seek_bill(b, &k->seek);
      continue;
    }
    fishman_taken(b);
    fishman_add(b, &FISHMAN_RUN_ACTOR_ASK);
    if (k->someone)
      fishman_taken(b);
    else
      fishman_add(b, &FISHMAN_RUN_WALK_TAKE);
  }
  fishman_add(b, &FISHMAN_RUN_RTS);
}

// `$81:DA20`, its `RTS` too: the pass on land from whoever is nearest.
static void fishman_stalk_on_bill(FishmanBill* b) {
  const FishmanLog* log = b->log;
  const bool fast = b->in->fastrom;
  fishman_add(b, &FISHMAN_RUN_STALK_NEAREST);
  switch (log->stalk) {
    case FISHMAN_STALK_SWEEPS:
    case FISHMAN_STALK_BESIDE:
      fishman_taken(b);
      fishman_add(b, &FISHMAN_RUN_STALK_NEAR);
      fishman_add(b, log->beside_negative ? &FISHMAN_RUN_NEGATE
                                          : &FISHMAN_RUN_TAKEN);
      fishman_add(b, &FISHMAN_RUN_BAND);
      if (log->stalk == FISHMAN_STALK_SWEEPS) {
        fishman_add(b, &FISHMAN_RUN_JMP);
        fishman_sweep_set_bill(b);
        return;
      }
      fishman_taken(b);
      break;
    case FISHMAN_STALK_LEFT:
    case FISHMAN_STALK_GOES_ABOUT:
      fishman_add(b, &FISHMAN_RUN_BAND);
      if (fishman_players_bill(b)) {
        fishman_add(b, &FISHMAN_RUN_LEAVE);
        fishman_add(b, &FISHMAN_RUN_RTS);
      } else {
        fishman_add(b, &FISHMAN_RUN_JMP);
        fishman_add(b, &FISHMAN_RUN_SET_STATE);
      }
      return;
    default:
      fishman_add(b, &FISHMAN_RUN_BAND);
      fishman_taken(b);
      break;
  }
  fishman_add(b, &FISHMAN_RUN_STALK_STEP);
  b->calls += actor_snap_cycles(&log->snap[b->bearings], fast) +
              actor_bearing_cycles(&log->bearing[b->bearings], fast);
  b->bearings++;
  fishman_walk_bill(b);
  fishman_add(b, &FISHMAN_RUN_RTS);
}

// `$81:DA1D`: with water to go back to, as far as its sleep.
static void fishman_stalk_bill(FishmanBill* b) {
  const FishmanLog* log = b->log;
  fishman_add(b, &FISHMAN_RUN_JSR);
  b->calls += wander_cycles(&log->wander, b->in);
  if (log->stalk == FISHMAN_STALK_FOUND_WATER) {
    fishman_add(b, &FISHMAN_RUN_WAIT);
    return;
  }
  fishman_add(b, &FISHMAN_RUN_RTS);  // the wander's
  fishman_stalk_on_bill(b);
}

// `$81:E31C`, as far as its pictures.
static void fishman_sweep_turn_bill(FishmanBill* b) {
  const FishmanLog* log = b->log;
  fishman_add(b, &FISHMAN_RUN_SWEEP_FACE);
  b->calls += actor_bearing_cycles(&log->bearing[b->bearings], b->in->fastrom);
  b->bearings++;
  if (log->faces_back) {
    fishman_taken(b);
    fishman_add(b, &FISHMAN_RUN_SWEEP_MIRROR);
  } else {
    fishman_add(b, &FISHMAN_RUN_SWEEP_PLAIN);
    fishman_taken(b);
  }
  fishman_add(b, &FISHMAN_RUN_SWEEP_LIST);
}

// `$81:E610`, its `RTS` too.
static void fishman_show_bill(FishmanBill* b) {
  const FishmanLog* log = b->log;
  if (fishman_players_bill(b)) {
    fishman_add(b, &FISHMAN_RUN_LEAVE);
    fishman_add(b, &FISHMAN_RUN_RTS);
    return;
  }
  fishman_add(b, &FISHMAN_RUN_SHOW_FORM);
  if (log->show == FISHMAN_SHOW_FLYING) {
    fishman_taken(b);
  } else {
    fishman_add(b, &FISHMAN_RUN_BRANCH);
    if (log->show == FISHMAN_SHOW_SWIMMING) fishman_taken(b);
    fishman_add(b, &FISHMAN_RUN_PICTURE_WAIT);
    if (!log->new_picture) {
      fishman_taken(b);
    } else if (log->show == FISHMAN_SHOW_SWIMMING) {
      fishman_add(b, &FISHMAN_RUN_SWIM_PICTURE);
      fishman_add(b, log->picture_wrapped ? &FISHMAN_RUN_SWIM_PICTURE_WRAP
                                          : &FISHMAN_RUN_TAKEN);
      fishman_add(b, &FISHMAN_RUN_SWIM_PICTURE_STORE);
    } else {
      fishman_add(b, &FISHMAN_RUN_STAND_PICTURE);
      fishman_taken(b);  // the `BCS` to the mirror, or the `BRA` round it
      fishman_add(b, log->mirrored ? &FISHMAN_RUN_STAND_PICTURE_MIRROR
                                   : &FISHMAN_RUN_STAND_PICTURE_PLAIN);
      fishman_add(b, &FISHMAN_RUN_STAND_PICTURE_STORE);
    }
  }
  // Everything but the swimming pictures goes by the `BRA` at `$E65A`.
  if (log->show != FISHMAN_SHOW_SWIMMING) {
    fishman_add(b, &FISHMAN_RUN_BRANCH);
    fishman_taken(b);
  }
  fishman_add(b, &FISHMAN_RUN_PLACE);
}

// The tests put their scratch on page zero, and the tables are read through
// the data bank. So are its record and the one it is after, which have to be
// in the WRAM bank `$81` mirrors. Only lining up reads the one it is after
// without having just found it.
static bool fishman_frame_ok(const Wram* w, const CosimRegs* in) {
  if (!body_ok(in) || in->d < 0x0100 || in->db != FISHMAN_BANK) return false;
  const uint16_t state = wram_r16(w, (uint16_t)(in->d + FISHMAN_DP_STATE));
  const bool lining_up = state == FISHMAN_STATE_LINE_UP_DOWN ||
                         state == FISHMAN_STATE_LINE_UP_ACROSS ||
                         state == FISHMAN_STATE_LURK;
  return wram_r16(w, (uint16_t)(in->d + FISHMAN_DP_RECORD)) < 0x1f00 &&
         (!lining_up ||
          wram_r16(w, (uint16_t)(in->d + FISHMAN_DP_TARGET)) < 0x1f00) &&
         fishman_frame_supported(w, in->d);
}

// A pass that stops to look about is the ROM's, and only running it says.
static bool guard_fishman_frame(Wram* scratch, const Rom* rom,
                                const CosimRegs* in) {
  FishmanLog log;
  fishman_frame(scratch, rom, &FISHMAN_LOOP, in->d, in->s,
                (in->p & PORT_P_C) != 0, &log);
  return !log.declined;
}

// The end of a pass, from the `JSR` that shows it.
static void fishman_end_bill(FishmanBill* b, bool stays) {
  fishman_add(b, &FISHMAN_RUN_JSR);
  fishman_show_bill(b);
  fishman_add(b, &FISHMAN_RUN_FATE);
  if (stays) {
    fishman_taken(b);
    fishman_add(b, &FISHMAN_RUN_SLEEP);
  }
}

static void fishman_charge(FishmanBill* b) {
  const FishmanLog* log = b->log;
  const CosimRegs* in = b->in;
  const bool fast = in->fastrom;
  b->calls += nearest_cycles(&log->nearest, fast) +
              at_point_cycles(&log->at_point, fast);
  for (int i = 0; i < log->draws && i < FISHMAN_MAX_DRAWS; i++)
    b->calls += rng_cycles(log->draw_overflow[i], fast);
  cosim_cost(b->calls +
             cosim_run_cycles_dp(&b->own, fetch_fast(in),
                                 (in->d & 0x00ffu) != 0) +
             cosim_run_cycles_dp(&b->zero, fetch_fast(in), false));
}

// What a stretch that finished a pass leaves: A, and the flags it wrote.
static void fishman_woken_out(const PortCpu* c, const FishmanLog* log,
                              CosimRegs* out) {
  cpu_to(c, out);
  out->regs = COSIM_REG_A;
  out->p_keep =
      (uint8_t)((log->c_set ? 0 : PORT_P_C) | (log->v_set ? 0 : PORT_P_V));
}

// It leaves by the `JSL thread_yield` with the tick count in A, or past the
// test of its fate with that in A. Or it stops in the middle of a body, at
// a sleep or a list of pictures.
static void fishman_frame_run(Wram* w, const Rom* rom, const CosimRegs* in,
                              CosimRegs* out, const FishmanLoop* loop) {
  static const uint32_t STOP_PC[] = {
      [FISHMAN_STOP_LEAP] = FISHMAN_LEAP_SLEEP_PC,
      [FISHMAN_STOP_DIVE] = FISHMAN_DIVE_SLEEP_PC,
      [FISHMAN_STOP_SWEEP] = FISHMAN_SWEEP_LIST_PC,
      [FISHMAN_STOP_SPLASH] = FISHMAN_SPLASH_LIST_PC,
  };
  FishmanLog log;
  const bool stays = fishman_frame(w, rom, loop, in->d, in->s,
                                   (in->p & PORT_P_C) != 0,
                                   &log) == FISHMAN_SLEEPS;
  const bool whole = log.stop == FISHMAN_STOP_PASS;

  FishmanBill b = {{0, 0, 0}, {0, 0, 0}, 0, &log, in, 0, 0, 0};
  fishman_add(&b, &FISHMAN_RUN_ENTER);
  switch (log.state) {
    case FISHMAN_STATE_SWIM:
      fishman_swim_bill(&b);
      break;
    case FISHMAN_STATE_SWIM_TURNED:
      fishman_swim_turned_bill(&b);
      break;
    case FISHMAN_STATE_CLOSE_IN:
      fishman_close_in_bill(&b);
      break;
    case FISHMAN_STATE_PATROL:
      fishman_patrol_bill(&b);
      break;
    case FISHMAN_STATE_LINE_UP_DOWN:
    case FISHMAN_STATE_LINE_UP_ACROSS:
      fishman_line_up_bill(&b);
      break;
    case FISHMAN_STATE_FLIGHT:
    case FISHMAN_STATE_DIVE:
      fishman_fly_bill(&b);
      break;
    case FISHMAN_STATE_STALK:
      fishman_stalk_bill(&b);
      break;
    case FISHMAN_STATE_LURK:
      fishman_sweep_turn_bill(&b);
      break;
    case FISHMAN_STATE_DIVE_BEGIN:
      fishman_add(&b, &FISHMAN_RUN_DIVE_BEGIN);
      fishman_fly_bill(&b);
      break;
    case FISHMAN_STATE_SPLASH:
      fishman_add(&b, &FISHMAN_RUN_SPLASH);
      break;
    default:
      fishman_land_bill(&b);
      break;
  }
  if (whole) fishman_end_bill(&b, stays);
  fishman_charge(&b);

  if (!whole) {
    out->pc = STOP_PC[log.stop];
    out->a = log.a;
    out->s = log.s;
  } else {
    out->pc = stays ? loop->yield_pc : loop->fate_pc;
    out->a =
        stays ? log.ticks : wram_r16(w, (uint16_t)(in->d + FISHMAN_DP_FATE));
  }
  out->regs = COSIM_REG_A;
  out->p = (uint8_t)(in->p & ~(PORT_P_N | PORT_P_Z | PORT_P_C | PORT_P_V));
  if (out->a & 0x8000u) out->p |= PORT_P_N;
  if (out->a == 0) out->p |= PORT_P_Z;
  if (log.c) out->p |= PORT_P_C;
  if (log.v) out->p |= PORT_P_V;
  out->p_keep = (uint8_t)((log.c_set ? 0 : PORT_P_C) | (log.v_set ? 0 : PORT_P_V));
}

static void shim_fishman_frame(Wram* w, const Rom* rom, const CosimRegs* in,
                               CosimRegs* out) {
  fishman_frame_run(w, rom, in, out, &FISHMAN_LOOP);
}

static void shim_fishman_patrol_frame(Wram* w, const Rom* rom,
                                      const CosimRegs* in, CosimRegs* out) {
  fishman_frame_run(w, rom, in, out, &FISHMAN_PATROL_LOOP);
}

static const uint32_t FISHMAN_FRAME_EXITS[] = {
    FISHMAN_YIELD_PC,       FISHMAN_FATE_PC,       FISHMAN_LEAP_SLEEP_PC,
    FISHMAN_DIVE_SLEEP_PC,  FISHMAN_SWEEP_LIST_PC, FISHMAN_SPLASH_LIST_PC};

// The stretches that begin where a body wakes. Each leaves as either loop
// does.
static const uint32_t FISHMAN_WOKEN_EXITS[] = {
    FISHMAN_YIELD_PC, FISHMAN_FATE_PC, FISHMAN_PATROL_YIELD_PC,
    FISHMAN_PATROL_FATE_PC};

static bool fishman_woken_ok(const Wram* w, const CosimRegs* in) {
  return body_ok(in) && in->d >= 0x0100 && in->db == FISHMAN_BANK &&
         cur_task_ok(w) &&
         wram_r16(w, (uint16_t)(in->d + FISHMAN_DP_RECORD)) < 0x1f00;
}

// The spot's bearing and the gap across, to the branch on it.
static void fishman_gap_x_bill(FishmanBill* b, const FishmanWakeLog* k) {
  fishman_add(b, &FISHMAN_RUN_GAP_X_HEAD);
  b->calls += actor_bearing_point_cycles(k->same_row, k->same_column,
                                         b->in->fastrom);
  fishman_add(b, k->negative[0] ? &FISHMAN_RUN_LINE_NEGATE : &FISHMAN_RUN_TAKEN);
  fishman_add(b, &FISHMAN_RUN_GAP_X_TAIL);
}

// ...and the gap down, and the longer of the two.
static void fishman_gap_y_bill(FishmanBill* b, const FishmanWakeLog* k) {
  fishman_add(b, &FISHMAN_RUN_GAP_Y_HEAD);
  fishman_add(b, k->negative[1] ? &FISHMAN_RUN_LINE_NEGATE : &FISHMAN_RUN_TAKEN);
  fishman_add(b, &FISHMAN_RUN_GAP_Y_TAIL);
  fishman_add(b, k->across_longer ? &FISHMAN_RUN_GAP_LONGER : &FISHMAN_RUN_TAKEN);
}

static bool accepts_fishman_leap_wake(const Wram* w, const CosimRegs* in) {
  return fishman_woken_ok(w, in) &&
         fishman_leap_wake_supported(w, in->d, in->s);
}

static void shim_fishman_leap_wake(Wram* w, const Rom* rom,
                                   const CosimRegs* in, CosimRegs* out) {
  PortCpu c;
  FishmanWakeLog k;
  cpu_from(in, &c);
  const bool stays = fishman_leap_wake(w, rom, &c, &k) == FISHMAN_SLEEPS;
  fishman_woken_out(&c, &k.pass, out);

  FishmanBill b = {{0, 0, 0}, {0, 0, 0}, 0, &k.pass, in, 0, 0, 0};
  fishman_add(&b, &FISHMAN_RUN_WAKE_BACK);
  fishman_add(&b, &FISHMAN_RUN_BRANCH);
  fishman_taken(&b);
  fishman_add(&b, &FISHMAN_RUN_JMP);
  fishman_gap_x_bill(&b, &k);
  if (k.stays) {
    fishman_taken(&b);
    fishman_add(&b, &FISHMAN_RUN_RTS);
  } else {
    fishman_gap_y_bill(&b, &k);
    fishman_add(&b, &FISHMAN_RUN_LEAP_SPAN);
    fishman_add(&b, &FISHMAN_RUN_LEAP_FORM);
    if (k.faces_cleared) {
      fishman_taken(&b);
      fishman_add(&b, &FISHMAN_RUN_LEAP_FACE_OFF);
    } else {
      fishman_add(&b, &FISHMAN_RUN_LEAP_FACE_ON);
      fishman_taken(&b);
    }
    fishman_add(&b, &FISHMAN_RUN_LEAP_DRESS);
    b.calls += thread_spawn_cycles(k.splash_slot, rom, in->fastrom);
  }
  fishman_end_bill(&b, stays);
  fishman_charge(&b);
}

static bool accepts_fishman_dive_wake(const Wram* w, const CosimRegs* in) {
  return fishman_woken_ok(w, in) &&
         fishman_dive_wake_supported(w, in->d, in->s);
}

// The rest of its pass on land may find water past where it is stopped,
// which is the ROM's, and only running it says.
static bool guard_fishman_dive_wake(Wram* scratch, const Rom* rom,
                                    const CosimRegs* in) {
  if (!accepts_fishman_dive_wake(scratch, in)) return false;
  PortCpu c;
  FishmanWakeLog k;
  cpu_from(in, &c);
  fishman_dive_wake(scratch, rom, &c, &k);
  return !k.pass.declined;
}

static void shim_fishman_dive_wake(Wram* w, const Rom* rom,
                                   const CosimRegs* in, CosimRegs* out) {
  PortCpu c;
  FishmanWakeLog k;
  cpu_from(in, &c);
  const bool stays = fishman_dive_wake(w, rom, &c, &k) == FISHMAN_SLEEPS;
  fishman_woken_out(&c, &k.pass, out);

  FishmanBill b = {{0, 0, 0}, {0, 0, 0}, 0, &k.pass, in, 0, 0, 0};
  fishman_gap_x_bill(&b, &k);
  if (k.stays) {
    fishman_add(&b, &FISHMAN_RUN_JMP);
    fishman_add(&b, &FISHMAN_RUN_JMP);
  } else {
    fishman_taken(&b);
    fishman_gap_y_bill(&b, &k);
    fishman_add(&b, &FISHMAN_RUN_DIVE_SPAN);
  }
  fishman_add(&b, &FISHMAN_RUN_SET_STATE);
  fishman_stalk_on_bill(&b);
  fishman_end_bill(&b, stays);
  fishman_charge(&b);
}

static bool accepts_fishman_after(const Wram* w, const CosimRegs* in) {
  return fishman_woken_ok(w, in) && fishman_after_supported(w, in->d, in->s);
}

static void shim_fishman_sweep_after(Wram* w, const Rom* rom,
                                     const CosimRegs* in, CosimRegs* out) {
  PortCpu c;
  FishmanLog log;
  bool wants = false;
  cpu_from(in, &c);
  const bool stays =
      fishman_sweep_after(w, rom, &c, &log, &wants) == FISHMAN_SLEEPS;
  fishman_woken_out(&c, &log, out);

  FishmanBill b = {{0, 0, 0}, {0, 0, 0}, 0, &log, in, 0, 0, 0};
  fishman_add(&b, &FISHMAN_RUN_SWEEP_AFTER);
  fishman_add(&b, wants ? &FISHMAN_RUN_WANT_WATER : &FISHMAN_RUN_TAKEN);
  fishman_add(&b, &FISHMAN_RUN_JMP);
  fishman_add(&b, &FISHMAN_RUN_SET_STATE);
  fishman_end_bill(&b, stays);
  fishman_charge(&b);
}

static void shim_fishman_splash_after(Wram* w, const Rom* rom,
                                      const CosimRegs* in, CosimRegs* out) {
  PortCpu c;
  FishmanLog log;
  cpu_from(in, &c);
  const bool stays = fishman_splash_after(w, rom, &c, &log) == FISHMAN_SLEEPS;
  fishman_woken_out(&c, &log, out);

  FishmanBill b = {{0, 0, 0}, {0, 0, 0}, 0, &log, in, 0, 0, 0};
  fishman_add(&b, &FISHMAN_RUN_SPLASH_DRESS);
  fishman_add(&b, &FISHMAN_RUN_ASHORE);  // `$DD91` has the same instructions
  fishman_add(&b, &FISHMAN_RUN_SET_STATE);
  fishman_end_bill(&b, stays);
  fishman_charge(&b);
}
// The beginning and the plain end of the one that patrols. `$80:9D5B`
// runs on absolute addresses: both tests, or the first alone when the load
// says no.
static const CosimRun FISHMAN_RUN_ROOM = {158, 15, 0};       // $80:9D5B-$9D69
static const CosimRun FISHMAN_RUN_ROOM_LOAD = {112, 9, 0};   // ...by its BCS
static const CosimRun FISHMAN_RUN_BEGIN_ASK = {66, 6, 0};    // $E51A JSL : BCC
static const CosimRun FISHMAN_RUN_BEGIN_TILE = {158, 16, 2};  // $E523-$E532, to the BEQ
static const CosimRun FISHMAN_RUN_BEGIN_LOAD = {138, 13, 0};  // $E536-$E542, the JSR too
static const CosimRun FISHMAN_RUN_BEGIN_DRESS = {1268, 110, 17};  // $E413-$E480
static const CosimRun FISHMAN_RUN_BEGIN_WAY = {132, 13, 2};  // $E543-$E54F, the JSR too
static const CosimRun FISHMAN_RUN_BEGIN_ALONE = {62 + 6, 4, 1};  // $DEEB DEC $0A : BRA
static const CosimRun FISHMAN_RUN_END_HEAD = {58, 7, 1};     // $E567 LDX # : LDA $22 : BEQ
static const CosimRun FISHMAN_RUN_END_LOAD = {110, 12, 0};   // $E59A-$E5A5, to the BMI
static const CosimRun FISHMAN_RUN_END_FREE = {140, 13, 2};   // $E5A6-$E5B2, to the BEQ

// `$81:E1D6`, to either `RTS`. Its page is zero from the `TCD`, and nothing
// before that reads the caller's.
static const CosimRun FISHMAN_RUN_LANDING_OUT = {46, 2, 0};  // PLD : CLC, or SEC

static void shim_fishman_landing(Wram* w, const Rom* rom, const CosimRegs* in,
                                 CosimRegs* out) {
  (void)rom;
  static const CosimRun* const TILES[] = {
      &FISHMAN_RUN_LAND_TILE_1, &FISHMAN_RUN_LAND_TILE_2,
      &FISHMAN_RUN_LAND_TILE_3, &FISHMAN_RUN_LAND_TILE_4,
      &FISHMAN_RUN_LAND_TILE_5, &FISHMAN_RUN_LAND_TILE_6};
  PortCpu c;
  FishmanTiles t;
  cpu_from(in, &c);
  fishman_landing(w, &c, &t);
  cpu_to(&c, out);
  CosimRun run = {0, 0, 0};
  run_add(&run, &FISHMAN_RUN_LAND_HEAD, 1);
  for (int i = 0; i < t.tiles; i++) run_add(&run, TILES[i], 1);
  if (!t.all) run_add(&run, &FISHMAN_RUN_TAKEN, 1);
  run_add(&run, &FISHMAN_RUN_LANDING_OUT, 1);
  cosim_cost(cosim_run_cycles_dp(&run, fetch_fast(in), false));
}

static const uint32_t FISHMAN_LANDING_EXITS[] = {FISHMAN_LANDING_YES_PC,
                                                 FISHMAN_LANDING_NO_PC};

// `$81:E381`: a tick of its sweep on land. See `port/fishman.h`.
static const CosimRun FSW_RUN_COUNT = {62, 4, 1};    // DEC $26 : BNE
static const CosimRun FSW_RUN_PLACE = {360, 36, 4};  // $E355-$E374
static const CosimRun FSW_RUN_WRAP = {18, 3, 0};     // LDA #$0000
static const CosimRun FSW_RUN_SLEEP = {46, 5, 1};    // STA $44 : LDA #$0001
static const CosimRun FSW_RUN_OVER = {28, 2, 1};     // LDA $42
static const CosimRun FSW_RUN_FREE = {54, 4, 0};     // JSL actor_slot_free
static const CosimRun FSW_RUN_DONE = {64, 8, 1};     // $E38B LDA # : STA $42 : LDA #

static bool accepts_fishman_sweep(const Wram* w, const CosimRegs* in) {
  return body_ok(in) && in->d >= 0x0100 && in->db == FISHMAN_BANK &&
         fishman_sweep_supported(w, in->d);
}

static void shim_fishman_sweep_tick(Wram* w, const Rom* rom,
                                    const CosimRegs* in, CosimRegs* out) {
  PortCpu c;
  bool wrapped = false;
  int place = 0;
  int freed = 0;
  cpu_from(in, &c);
  const bool on = fishman_sweep_tick(w, rom, &c, &wrapped, &place);
  cpu_to(&c, out);
  CosimRun run = {0, 0, 0};
  run_add(&run, &FSW_RUN_COUNT, 1);
  if (on) {
    run_add(&run, &RUN_TAKEN, 1);
    run_add(&run, &FSW_RUN_PLACE, 1);
    run_add(&run, wrapped ? &FSW_RUN_WRAP : &RUN_TAKEN, 1);
    run_add(&run, &FSW_RUN_SLEEP, 1);
  } else {
    run_add(&run, &FSW_RUN_OVER, 1);
    run_add(&run, &FSW_RUN_FREE, 1);
    run_add(&run, &FSW_RUN_DONE, 1);
    freed = saucer_free_cycles(place, in->fastrom);
  }
  cosim_cost(freed + cosim_run_cycles_dp(&run, fetch_fast(in),
                                         (in->d & 0xffu) != 0));
}

static const uint32_t FISHMAN_SWEEP_EXITS[] = {FISHMAN_SWEEP_YIELD_PC,
                                               FISHMAN_SWEEP_DONE_PC};

// `$81:E346`: the sweep begun, to its first sleep.
static bool accepts_fishman_sweep_begin(const Wram* w, const CosimRegs* in) {
  return fishman_woken_ok(w, in) &&
         fishman_sweep_begin_supported(w, in->d, in->s);
}

// No record free is the ROM's, which does not ask.
static bool guard_fishman_sweep_begin(Wram* scratch, const Rom* rom,
                                      const CosimRegs* in) {
  if (!accepts_fishman_sweep_begin(scratch, in)) return false;
  PortCpu c;
  uint16_t record = 0;
  bool wrapped = false;
  cpu_from(in, &c);
  return fishman_sweep_begin(scratch, rom, &c, &record, &wrapped);
}

static void shim_fishman_sweep_begin(Wram* w, const Rom* rom,
                                     const CosimRegs* in, CosimRegs* out) {
  PortCpu c;
  uint16_t record = 0;
  bool wrapped = false;
  cpu_from(in, &c);
  fishman_sweep_begin(w, rom, &c, &record, &wrapped);
  cpu_to(&c, out);
  CosimRun run = {0, 0, 0};
  run_add(&run, &FISHMAN_RUN_JSR, 1);
  run_add(&run, &FISHMAN_RUN_BLOW_DRESS, 1);
  run_add(&run, &FISHMAN_RUN_SWEEP_SET, 1);
  run_add(&run, &FSW_RUN_PLACE, 1);
  run_add(&run, wrapped ? &FSW_RUN_WRAP : &RUN_TAKEN, 1);
  run_add(&run, &FSW_RUN_SLEEP, 1);
  cosim_cost(saucer_alloc_cycles(record, in->fastrom) +
             cosim_run_cycles_dp(&run, fetch_fast(in), (in->d & 0xffu) != 0));
}

static const uint32_t FISHMAN_SWEEP_BEGIN_EXITS[] = {FISHMAN_SWEEP_YIELD_PC};

// `$81:E72C`: the splash a leap leaves, to its pictures.
static const CosimRun FISHMAN_RUN_SPLASH_BEGIN = {750, 69, 3};  // $E72C-$E770

static bool accepts_fishman_splash_begin(const Wram* w, const CosimRegs* in) {
  return body_ok(in) && in->d >= 0x0100 && in->db == FISHMAN_BANK &&
         cur_task_ok(w);
}

// No record free is the ROM's, which does not ask.
static bool guard_fishman_splash_begin(Wram* scratch, const Rom* rom,
                                       const CosimRegs* in) {
  (void)rom;
  if (!accepts_fishman_splash_begin(scratch, in)) return false;
  PortCpu c;
  uint16_t record = 0;
  cpu_from(in, &c);
  return fishman_splash_begin(scratch, &c, &record);
}

static void shim_fishman_splash_begin(Wram* w, const Rom* rom,
                                      const CosimRegs* in, CosimRegs* out) {
  (void)rom;
  PortCpu c;
  uint16_t record = 0;
  cpu_from(in, &c);
  fishman_splash_begin(w, &c, &record);
  cpu_to(&c, out);
  cosim_cost(saucer_alloc_cycles(record, in->fastrom) +
             cosim_run_cycles_dp(&FISHMAN_RUN_SPLASH_BEGIN, fetch_fast(in),
                                 (in->d & 0xffu) != 0));
}

static const uint32_t FISHMAN_SPLASH_BEGIN_EXITS[] = {
    FISHMAN_SPLASH_BEGIN_LIST_PC};

static bool accepts_fishman_patrol_begin(const Wram* w, const CosimRegs* in) {
  (void)w;
  return body_ok(in) && in->d >= 0x0100 && in->db == FISHMAN_BANK;
}

// No record free is the ROM's, which goes on with what is none.
static bool guard_fishman_patrol_begin(Wram* scratch, const Rom* rom,
                                       const CosimRegs* in) {
  if (!accepts_fishman_patrol_begin(scratch, in)) return false;
  PortCpu c;
  FishmanBeginLog log;
  cpu_from(in, &c);
  fishman_patrol_begin(scratch, rom, &c, &log);
  return !log.declined;
}

static void shim_fishman_patrol_begin(Wram* w, const Rom* rom,
                                      const CosimRegs* in, CosimRegs* out) {
  PortCpu c;
  FishmanBeginLog log;
  cpu_from(in, &c);
  const bool load_full = wram_r16(w, W_SPAWN_LOAD) >= SPAWN_LOAD_MAX;
  fishman_patrol_begin(w, rom, &c, &log);
  cpu_to(&c, out);
  out->regs = COSIM_REG_A;
  if (log.v_unknown) out->p_keep = PORT_P_V;

  const bool fast = in->fastrom;
  CosimRun own = {0, 0, 0};
  int calls = cosim_run_cycles(
      log.how == FISHMAN_BEGIN_NO_ROOM && load_full ? &FISHMAN_RUN_ROOM_LOAD
                                                    : &FISHMAN_RUN_ROOM,
      fast);
  run_add(&own, &FISHMAN_RUN_BEGIN_ASK, 1);
  if (log.how == FISHMAN_BEGIN_NO_ROOM) {
    run_add(&own, &FISHMAN_RUN_JMP, 1);
  } else {
    run_add(&own, &FISHMAN_RUN_TAKEN, 1);
    run_add(&own, &FISHMAN_RUN_BEGIN_TILE, 1);
    calls += cosim_run_cycles(&TILE_ATTRS_RUN, fast);
    if (log.how == FISHMAN_BEGIN_NOT_WATER) {
      run_add(&own, &FISHMAN_RUN_JMP, 1);
    } else {
      run_add(&own, &FISHMAN_RUN_TAKEN, 1);
      run_add(&own, &FISHMAN_RUN_BEGIN_LOAD, 1);
      run_add(&own, &FISHMAN_RUN_BEGIN_DRESS, 1);
      calls += saucer_alloc_cycles(log.record, fast) +
               cosim_run_cycles(&SET_HANDLER_RUN, fast);
      run_add(&own, &FISHMAN_RUN_BEGIN_WAY, 1);
      run_add(&own, &FISHMAN_RUN_PATROL_AGAIN, 1);
      run_add(&own, &FISHMAN_RUN_PLAYERS, 1);
      calls += player_bearing_cycles(&log.players, fast);
      run_add(&own, log.alone ? &FISHMAN_RUN_BEGIN_ALONE : &FISHMAN_RUN_TAKEN,
              1);
      run_add(&own, &FISHMAN_RUN_RTS, 1);
      run_add(&own, &FISHMAN_RUN_SLEEP, 1);
    }
  }
  cosim_cost(calls + cosim_run_cycles_dp(&own, fetch_fast(in),
                                         (in->d & 0x00ffu) != 0));
}

static const uint32_t FISHMAN_PATROL_BEGIN_EXITS[] = {FISHMAN_PATROL_YIELD_PC,
                                                      FISHMAN_PATROL_RTL_PC};

static bool accepts_fishman_patrol_end(const Wram* w, const CosimRegs* in) {
  return body_ok(in) && in->d >= 0x0100 && in->db == FISHMAN_BANK &&
         fishman_patrol_end_supported(w, in->d);
}

static void shim_fishman_patrol_end(Wram* w, const Rom* rom,
                                    const CosimRegs* in, CosimRegs* out) {
  (void)rom;
  PortCpu c;
  FishmanEndLog log;
  cpu_from(in, &c);
  fishman_patrol_end(w, &c, &log);
  cpu_to(&c, out);
  CosimRun own = {0, 0, 0};
  run_add(&own, &FISHMAN_RUN_END_HEAD, 1);
  run_add(&own, &FISHMAN_RUN_TAKEN, 1);
  run_add(&own, &FISHMAN_RUN_END_LOAD, 1);
  run_add(&own, &FISHMAN_RUN_END_FREE, 1);
  run_add(&own, &FISHMAN_RUN_TAKEN, 1);
  cosim_cost(saucer_free_cycles(log.place, in->fastrom) +
             cosim_run_cycles_dp(&own, fetch_fast(in),
                                 (in->d & 0x00ffu) != 0));
}

static const uint32_t FISHMAN_PATROL_END_EXITS[] = {FISHMAN_PATROL_RTL_PC};

static const uint32_t FISHMAN_PATROL_FRAME_EXITS[] = {
    FISHMAN_PATROL_YIELD_PC, FISHMAN_PATROL_FATE_PC, FISHMAN_LEAP_SLEEP_PC,
    FISHMAN_DIVE_SLEEP_PC,   FISHMAN_SWEEP_LIST_PC,  FISHMAN_SPLASH_LIST_PC};

