static bool accepts_player_branch(const Wram* w, const CosimRegs* in) {
  const uint16_t state = wram_r16(w, (uint16_t)(in->d + 0x70));
  return accepts_body(w, in) && state < PLAYER_STATE_LIMIT && !(state & 1u);
}
