static const CosimRun MP_LIST = {716, 69, 0};    // $AC06-$AC46
static const CosimRun MP_ASK = {90, 10, 0};      // $AC47-$AC50
static const CosimRun MP_TAIL = {104, 4, 0};     // STZ $ED : PLD : RTL

static int tile_put_cycles(const TilePutRegs* r, bool fast) {
  // How many compares ran, whether the lone `BCS` did, and whether the last
  // branch of the test was taken.
  static const struct {
    int compares;
    bool bcs, taken;
  } TEST[] = {
      [TILE_PUT_LEFT_OF] = {1, false, true},
      [TILE_PUT_RIGHT_OF] = {2, false, true},
      [TILE_PUT_ABOVE] = {3, false, true},
      [TILE_PUT_LAST_ROW] = {4, false, true},
      [TILE_PUT_BELOW] = {4, true, true},
      [TILE_PUT_INSIDE] = {4, true, false},
  };
  const bool on_screen =
      r->window == TILE_PUT_LAST_ROW || r->window == TILE_PUT_INSIDE;
  CosimRun run = {0, 0, 0};
  run_add(&run, &MP_HEAD, 1);
  run_add(&run, r->over_sprites ? &MP_OVER : &RUN_TAKEN, 1);
  run_add(&run, &MP_WRITE, 1);
  run_add(&run, &MP_COMPARE, TEST[r->window].compares);
  if (TEST[r->window].bcs) run_add(&run, &MP_BCS, 1);
  if (TEST[r->window].taken) run_add(&run, &RUN_TAKEN, 1);
  run_add(&run, &MP_FLAG_RTS, 1);
  if (!on_screen) {
    run_add(&run, &RUN_TAKEN, 1);
  } else {
    run_add(&run, &MP_LIST, 1);
    run_add(&run, r->asked ? &MP_ASK : &RUN_TAKEN, 1);
  }
  run_add(&run, &MP_TAIL, 1);
  int cycles = cosim_run_cycles(&run, fast) +
               cosim_run_cycles(&TILE_ADDR_RUN, fast);
  if (r->asked) cycles += saucer_queue_a_cycles(r->slot, fast);
  return cycles;
}

// Its absolute reads are through the data bank, and it adds.
static bool accepts_map_tile_put(const Wram* w, const CosimRegs* in) {
  (void)w;
  return wide(in) && (in->p & PORT_P_D) == 0 && low_stack(in) &&
         (in->db & 0x40) == 0;
}

static void shim_map_tile_put(Wram* w, const Rom* rom, const CosimRegs* in,
                              CosimRegs* out) {
  TilePutRegs r;
  map_tile_put(w, rom, in->a, in->x, in->y, &r);
  cosim_cost(tile_put_cycles(&r, in->fastrom));
  out->a = r.a;
  out->x = r.x;
  out->y = r.y;
  out->c = r.c;
  out->n = (in->d & 0x8000u) != 0;
  out->z = in->d == 0;
  out->flags = COSIM_FLAG_N | COSIM_FLAG_Z | COSIM_FLAG_C;
}

// `$81:E8F1`, and `$81:FF05` at the end of it.
static const CosimRun SW_BEGIN = {1516 + 68, 136 + 5, 18 + 1};  // $E8F1-$E977
static const CosimRun SW_OP_TEST = {110, 10, 2};     // $FF05-$FF0C
static const CosimRun SW_OP_SET = {92 + 6, 8, 0};    // ORA : STA : BRA
static const CosimRun SW_OP_CLEAR = {80, 6, 0};      // AND : STA
static const CosimRun SW_PICTURE = {260, 19, 3};     // $FF1B-$FF29

// `$04` is twice a way of one to eight, and `$06` a player.
static bool accepts_swipe(const Wram* w, const CosimRegs* in) {
  if (!body_ok(in) || in->d < 0x0100 || in->db != SWIPE_BANK) return false;
  const uint16_t way = wram_r16(w, (uint16_t)(in->d + SWIPE_DP_WAY));
  return cur_task_ok(w) && way >= 2 && way < SWIPE_WAY_END && (way & 1) == 0 &&
         wram_r16(w, (uint16_t)(in->d + SWIPE_DP_OWNER)) < 0x1f00 &&
         (wram_r16(w, (uint16_t)(in->d + SWIPE_DP_PLAYER)) & ~2u) == 0;
}

// No record free is the ROM's: it goes on with what is none.
static bool guard_swipe_begin(Wram* scratch, const Rom* rom,
                              const CosimRegs* in) {
  if (!accepts_swipe(scratch, in)) return false;
  PortCpu c;
  SwipeBeginWork k = {0};
  cpu_from(in, &c);
  swipe_begin(scratch, rom, &c, &k);
  return !k.declined;
}

// Its own instructions into `run`, and what it calls handed back.
static int swipe_begin_bill(CosimRun* run, const SwipeBeginWork* k,
                            const CosimRegs* in) {
  run_add(run, &SW_BEGIN, 1);
  run_add(run, &SW_OP_TEST, 1);
  if (k->turned_over) {
    run_add(run, &SW_OP_SET, 1);
  } else {
    run_add(run, &RUN_TAKEN, 1);
    run_add(run, &SW_OP_CLEAR, 1);
  }
  run_add(run, &SW_PICTURE, 1);
  return saucer_alloc_cycles(k->record, in->fastrom) +
         cosim_run_cycles(&SET_HANDLER_RUN, in->fastrom);
}

static void shim_swipe_begin(Wram* w, const Rom* rom, const CosimRegs* in,
                             CosimRegs* out) {
  PortCpu c;
  SwipeBeginWork k = {0};
  cpu_from(in, &c);
  swipe_begin(w, rom, &c, &k);
  cpu_to(&c, out);
  CosimRun run = {0, 0, 0};
  const int calls = swipe_begin_bill(&run, &k, in);
  cosim_cost(calls +
             cosim_run_cycles_dp(&run, fetch_fast(in), (in->d & 0xffu) != 0));
}

// `$81:E979`. The tile's attributes are read on page zero, so that one
// instruction is not counted with the direct page's.
static const CosimRun SW_CUT_HEAD = {236, 22, 5};    // $E979-$E98A
static const CosimRun SW_CUT_NEXT = {62, 4, 1};      // DEC $4C : BMI
static const CosimRun SW_CUT_TILE = {276 + 276 + 94 + 52 + 186,
                                     22 + 19 + 9 + 2 + 15, 6 + 2};  // $E98F-$E9CD
static const CosimRun SW_CUT_SECOND = {54, 7, 0};    // $E9CE-$E9D4
static const CosimRun SW_CUT_TAIL = {40, 4, 1};      // LDA $48 : BEQ

// A look that cut nothing: its own instructions into `run`, and what it
// calls handed back.
static int swipe_cut_bill(CosimRun* run, const SwipeCutWork* k,
                          const CosimRegs* in) {
  run_add(run, &SW_CUT_HEAD, 1);
  run_add(run, &SW_CUT_NEXT, k->tiles + 1);
  run_add(run, &SW_CUT_TILE, k->tiles);
  run_add(run, &SW_CUT_SECOND, k->tiles);
  run_add(run, &SW_CUT_TAIL, 1);
  run_add(run, &RUN_TAKEN, k->tiles + 2);
  return k->tiles * cosim_run_cycles(&TILE_ADDR_RUN, in->fastrom);
}

static bool guard_swipe_cut(Wram* scratch, const Rom* rom,
                            const CosimRegs* in) {
  if (!accepts_swipe(scratch, in)) return false;
  PortCpu c;
  static SwipeCutWork k;
  k = (SwipeCutWork){0};
  cpu_from(in, &c);
  swipe_cut(scratch, rom, &c, &k);
  return !k.declined;
}

static void shim_swipe_cut(Wram* w, const Rom* rom, const CosimRegs* in,
                           CosimRegs* out) {
  PortCpu c;
  static SwipeCutWork k;
  k = (SwipeCutWork){0};
  cpu_from(in, &c);
  swipe_cut(w, rom, &c, &k);
  cpu_to(&c, out);
  if (k.overflow_unknown) out->p_keep = PORT_P_V;
  // A sound is not priced, and every cut ends in one. So what is priced is
  // a look that cut nothing: each tile takes both its branches.
  if (k.played) return;
  CosimRun run = {0, 0, 0};
  const int calls = swipe_cut_bill(&run, &k, in);
  cosim_cost(calls +
             cosim_run_cycles_dp(&run, fetch_fast(in), (in->d & 0xffu) != 0));
}

static const uint32_t SWIPE_BEGIN_EXITS[] = {SWIPE_BEGIN_RTS_PC};
static const uint32_t SWIPE_CUT_EXITS[] = {SWIPE_CUT_RTS_PC};

// ---------------------------------------------------------------------------
// What a level leaves on the ground, and the neighbours' list -- see
// `port/objects.h`
// ---------------------------------------------------------------------------

// `$80:C9A5`. The list is in the cartridge, and its bytes cost what a
// program's do.
static const CosimRun OL_HEAD = {36, 6, 0};        // $C9A5-$C9AA
static const CosimRun OL_ITEM = {448 + 6, 43, 3};  // $C9AB-$C9CF
static const CosimRun OL_END = {60 + 6, 6, 1};     // LDA [$00],Y : BEQ
static const CosimRun OL_TAIL = {148, 16, 0};      // $C9D0-$C9DF
static const CosimRun OL_RTS = {68, 3, 1};         // STZ $12 : RTS
// `$80:C9E3` and `$80:CAA8`, straight through.
static const CosimRun OS_RUN = {912, 81, 1};
static const CosimRun OF_RUN = {284, 23, 0};
// `$80:CABF`.
static const CosimRun OC_HEAD = {80, 7, 2};       // $CABF-$CAC5
static const CosimRun OC_MISS = {88 + 6, 9, 0};   // $CAC6-$CACE
static const CosimRun OC_HIT = {52 + 6, 5, 0};    // CMP : BEQ
static const CosimRun OC_FREE = {136, 12, 0};     // $CACF-$CADA
static const CosimRun OC_TAIL = {222, 18, 2};     // $CADB-$CAEC
static const CosimRun OC_RTS = {40, 1, 0};

// Its tables are read through the data bank, and so are its absolutes.
static bool accepts_object(const Wram* w, const CosimRegs* in) {
  return body_ok(in) && in->d >= 0x0100 && in->db == 0x80 && cur_task_ok(w);
}

static bool guard_object_list_parse(Wram* scratch, const Rom* rom,
                                    const CosimRegs* in) {
  if (!accepts_object(scratch, in)) return false;
  // A list in the cartridge, which is where the levels keep them.
  if (wram_r8(scratch, (uint16_t)(in->d + OBJECT_DP_LIST + 2)) < 0x80 ||
      wram_r16(scratch, (uint16_t)(in->d + OBJECT_DP_LIST)) < 0x8000)
    return false;
  PortCpu c;
  ObjectsWork k = {0};
  cpu_from(in, &c);
  object_list_parse(scratch, rom, &c, &k);
  return !k.declined;
}

static void shim_object_list_parse(Wram* w, const Rom* rom,
                                   const CosimRegs* in, CosimRegs* out) {
  PortCpu c;
  ObjectsWork k = {0};
  cpu_from(in, &c);
  object_list_parse(w, rom, &c, &k);
  ret_from_cpu(&c, out);
  CosimRun run = {0, 0, 0};
  run_add(&run, &OL_HEAD, 1);
  run_add(&run, &OL_ITEM, k.entries);
  run_add(&run, &OL_END, 1);
  run_add(&run, &OL_TAIL, 1);
  run_add(&run, &OL_RTS, 1);
  cosim_cost(cosim_run_cycles(&SET_HANDLER_RUN, in->fastrom) +
             cosim_run_cycles_dp(&run, fetch_fast(in), (in->d & 0xffu) != 0));
}

static bool guard_object_spawn(Wram* scratch, const Rom* rom,
                               const CosimRegs* in) {
  if (!accepts_object(scratch, in)) return false;
  const uint16_t entry = wram_r16(scratch, (uint16_t)(in->d + OBJECT_DP_ENTRY));
  if (entry >= OBJECT_SLOT_COUNT * 2 || (entry & 1)) return false;
  const uint16_t type = wram_r16(scratch, (uint16_t)(W_OBJECT_TYPE + entry));
  if (type >= OBJECT_TYPE_END || (type & 1)) return false;
  PortCpu c;
  ObjectsWork k = {0};
  cpu_from(in, &c);
  object_spawn(scratch, rom, &c, &k);
  return !k.declined;
}

static void shim_object_spawn(Wram* w, const Rom* rom, const CosimRegs* in,
                              CosimRegs* out) {
  PortCpu c;
  ObjectsWork k = {0};
  cpu_from(in, &c);
  object_spawn(w, rom, &c, &k);
  ret_from_cpu(&c, out);
  // Overflow is the allocator's.
  out->flags = COSIM_FLAG_N | COSIM_FLAG_Z | COSIM_FLAG_C;
  cosim_cost(saucer_alloc_cycles(k.record, in->fastrom) +
             cosim_run_cycles_dp(&OS_RUN, fetch_fast(in),
                                 (in->d & 0xffu) != 0));
}

static bool guard_object_free(Wram* scratch, const Rom* rom,
                              const CosimRegs* in) {
  (void)rom;
  if (!accepts_object(scratch, in)) return false;
  if (in->x >= OBJECT_SLOT_COUNT * 2 || (in->x & 1)) return false;
  PortCpu c;
  ObjectsWork k = {0};
  cpu_from(in, &c);
  object_free(scratch, &c, &k);
  return !k.declined;
}

static void shim_object_free(Wram* w, const Rom* rom, const CosimRegs* in,
                             CosimRegs* out) {
  (void)rom;
  PortCpu c;
  ObjectsWork k = {0};
  cpu_from(in, &c);
  object_free(w, &c, &k);
  ret_from_cpu(&c, out);
  out->flags = COSIM_FLAG_N | COSIM_FLAG_Z | COSIM_FLAG_C;
  cosim_cost(saucer_free_cycles(k.place[0], in->fastrom) +
             cosim_run_cycles(&OF_RUN, fetch_fast(in)));
}

static bool guard_object_collect(Wram* scratch, const Rom* rom,
                                 const CosimRegs* in) {
  (void)rom;
  if (!accepts_object(scratch, in)) return false;
  const uint16_t left =
      wram_r16(scratch, (uint16_t)(in->d + OBJECT_DP_COLLECTED));
  if (left == 0 || (left & 1) || left > OBJECT_COLLECT_MAX * 2) return false;
  PortCpu c;
  ObjectsWork k = {0};
  cpu_from(in, &c);
  object_collect(scratch, &c, &k);
  return !k.declined;
}

static void shim_object_collect(Wram* w, const Rom* rom, const CosimRegs* in,
                                CosimRegs* out) {
  (void)rom;
  PortCpu c;
  ObjectsWork k = {0};
  cpu_from(in, &c);
  object_collect(w, &c, &k);
  ret_from_cpu(&c, out);
  CosimRun run = {0, 0, 0};
  int cycles = 0;
  for (int i = 0; i < k.collected; i++) {
    run_add(&run, &OC_HEAD, 1);
    run_add(&run, &OC_MISS, k.scanned[i]);
    run_add(&run, &OC_HIT, 1);
    run_add(&run, &OC_FREE, 1);
    run_add(&run, &OC_TAIL, 1);
    if (i + 1 < k.collected) run_add(&run, &RUN_TAKEN, 1);
    cycles += saucer_free_cycles(k.place[i], in->fastrom);
  }
  run_add(&run, &OC_RTS, 1);
  cosim_cost(cycles + cosim_run_cycles_dp(&run, fetch_fast(in),
                                          (in->d & 0xffu) != 0));
}

// `$82:DB46`, to the `SEP` its hardware writes begin with.
static const CosimRun VL_HEAD = {132, 14, 2};      // $DB46-$DB53
static const CosimRun VL_TEST = {78, 9, 1};        // LDY # : LDA [$28],Y : BEQ
static const CosimRun VL_EQ = {52 + 6, 6, 0};      // CMP long : BEQ
static const CosimRun VL_LT = {64, 8, 0};          // ...and BCS
static const CosimRun VL_KEEP = {456 + 6, 44, 4};  // $DB63-$DB8A
static const CosimRun VL_TAIL = {98, 11, 0};       // $DB8B-$DB95

static bool guard_victim_list_parse(Wram* scratch, const Rom* rom,
                                    const CosimRegs* in) {
  if (!body_ok(in) || (in->a & 0xffu) < 0x80 || in->x < 0x8000) return false;
  PortCpu c;
  VictimsWork k = {0};
  cpu_from(in, &c);
  victim_list_parse(scratch, rom, &c, &k);
  return !k.declined;
}

static void shim_victim_list_parse(Wram* w, const Rom* rom,
                                   const CosimRegs* in, CosimRegs* out) {
  PortCpu c;
  VictimsWork k = {0};
  cpu_from(in, &c);
  victim_list_parse(w, rom, &c, &k);
  cpu_to(&c, out);
  CosimRun run = {0, 0, 0};
  run_add(&run, &VL_HEAD, 1);
  run_add(&run, &VL_TEST, k.entries + 1);
  run_add(&run, &VL_EQ, k.equal);
  run_add(&run, &VL_LT, k.entries - k.equal);
  run_add(&run, &VL_KEEP, k.entries);
  if (k.ended_past) run_add(&run, &VL_LT, 1);
  run_add(&run, &RUN_TAKEN, 1);  // the branch out
  run_add(&run, &VL_TAIL, 1);
  cosim_cost(cosim_run_cycles_dp(&run, fetch_fast(in), (in->d & 0xffu) != 0));
}

static const uint32_t VICTIM_LIST_PARSE_EXITS[] = {VICTIM_LIST_PARSE_DONE_PC};

// `$81:817E`: thirty-two turns, of which the last falls through.
static const CosimRun VT_ZERO = {36, 6, 0};
static const CosimRun VT_LOOP = {116, 12, 0};
static const CosimRun VT_RTL = {42, 1, 0};

static bool accepts_victim_tables_clear(const Wram* w, const CosimRegs* in) {
  (void)w;
  return wide(in) && low_stack(in);
}

static void shim_victim_tables_clear(Wram* w, const Rom* rom,
                                     const CosimRegs* in, CosimRegs* out) {
  (void)rom;
  PortCpu c;
  cpu_from(in, &c);
  victim_tables_clear(w, &c);
  ret_from_cpu(&c, out);
  CosimRun run = {0, 0, 0};
  run_add(&run, &VT_ZERO, 1);
  run_add(&run, &VT_LOOP, VICTIM_TABLE_BYTES / 2);
  run_add(&run, &RUN_TAKEN, VICTIM_TABLE_BYTES / 2 - 1);
  run_add(&run, &VT_RTL, 1);
  cosim_cost(cosim_run_cycles(&run, fetch_fast(in)));
}

// `$81:81A2`. The entry is read through the data bank, which is the list's.
static const CosimRun VB_HEAD = {458, 38, 11};  // $81A2-$81C3
static const CosimRun VB_EQ = {52 + 6, 6, 0};   // CMP long : BEQ
static const CosimRun VB_LT = {64, 8, 0};       // ...and BCS
static const CosimRun VB_SPAWN = {268, 19, 2};  // $81CC-$81DA
static const CosimRun VB_TAIL = {12 + 6 + 180, 2 + 17, 1};  // BPL, $81DE-$81EE

static bool guard_victim_start(Wram* scratch, const Rom* rom,
                               const CosimRegs* in) {
  if (!body_ok(in) || in->d < 0x0100 || in->db != 0x9f) return false;
  if (wram_r16(scratch, (uint16_t)(in->d + VICTIM_DP_ENTRY)) >=
          VICTIM_TABLE_BYTES ||
      wram_r16(scratch, (uint16_t)(in->d + VICTIM_DP_START_LIST)) < 0x8000)
    return false;
  PortCpu c;
  VictimsWork k = {0};
  cpu_from(in, &c);
  victim_start(scratch, rom, &c, &k);
  return !k.declined;
}

static void shim_victim_start(Wram* w, const Rom* rom, const CosimRegs* in,
                              CosimRegs* out) {
  PortCpu c;
  VictimsWork k = {0};
  cpu_from(in, &c);
  victim_start(w, rom, &c, &k);
  ret_from_cpu(&c, out);
  // Carry and overflow are the spawn's.
  out->flags = COSIM_FLAG_N | COSIM_FLAG_Z;
  CosimRun run = {0, 0, 0};
  run_add(&run, &VB_HEAD, 1);
  if (k.ungated) {
    run_add(&run, &RUN_TAKEN, 1);
  } else {
    run_add(&run, k.at_gate ? &VB_EQ : &VB_LT, 1);
  }
  run_add(&run, &VB_SPAWN, 1);
  run_add(&run, &VB_TAIL, 1);
  cosim_cost(thread_spawn_cycles(k.slot, rom, in->fastrom) +
             cosim_run_cycles_dp(&run, fetch_fast(in), (in->d & 0xffu) != 0));
}

