  cpu_from(in, &c);
  tracker_begin(w, rom, &c, &record);
  cpu_to(&c, out);
  cosim_cost(saucer_alloc_cycles(record, in->fastrom) +
             cosim_run_cycles(&SET_HANDLER_RUN, in->fastrom) +
             cosim_run_cycles_dp(&TRACKER_RUN_BEGIN, fetch_fast(in),
                                 (in->d & 0xffu) != 0));
